function makeModules(f){const picks=(f.interests||[]).filter(k=>MODULES[k]);const first=picks[0]||'creative';const second=picks.find(k=>k!==first&&MODULES[k].day!==MODULES[first].day)||(['creative','computing','history'].includes(first)?'music':'creative');return ['core1','core2',first,second,'sustainability','media'];}

const N={
 /* Form A simulation — modelled on handbook sections A1–A11, not a registration form */
 fa1:{place:'east',speaker:'Julie · academic adviser',portrait:'adviser',title:'A conversation, not a form to fill alone',text:s=>`After the welcome, Julie finds a quieter spot outside East Quad and turns her screen so you can both see the advising form. “This is our first advising conversation,” she says. “I want to hear what brought you to Arts, what you'd like to investigate, and anything that might make studying difficult. I can record directions and follow-up actions. The form won't automatically enrol you on modules.”\n\n“Let's start with you. When you think about your first year, what are you curious about?”`,options:[opt('“Creative work, design and making things.”','fa2',{form:{interest:'creative',confidence:'exploring'}}),opt('“Music, culture and how people communicate.”','fa2',{form:{interest:'music',confidence:'exploring'}}),opt('“Computing, technology and problem-solving.”','fa2',{form:{interest:'computing',confidence:'exploring'}}),opt('“Food, health and the wider world.”','fa2',{form:{interest:'food',confidence:'exploring'}})]},
 fa2:{place:'east',speaker:'Julie · academic adviser',portrait:'adviser',title:'Your second interest might surprise you',text:s=>`“You've mentioned ${MODULES[s.formA.interests[0]]?.title||'a subject'},” Julie says, jotting it down. “You do not have to commit to a Major today. Sometimes the second or third area you explore turns out to matter just as much.”\n\nShe asks what else you would like to sample. Someone calls to a friend across the forecourt. You realise the first semester could introduce you to a subject you haven't studied before.`,options:[opt('“History and the stories of Dublin.”','fa3',{form:{interest:'history'}}),opt('“Language and identity.”','fa3',{form:{interest:'language'}}),opt('“Music and culture.”','fa3',{form:{interest:'music'}}),opt('“Computing and digital ideas.”','fa3',{form:{interest:'computing'}})]},
 fa3:{place:'east',speaker:'Julie · academic adviser',portrait:'adviser',title:'How certain are you?',text:s=>`Julie reads back your interests: ${(s.formA.interests||[]).map(k=>MODULES[k]?.title).join(' and ')}. “That gives us a starting point. But the form has another question: how confident are you about a future Major or perhaps a Minor? Being unsure is a perfectly useful answer.”\n\nShe opens the programme pathway diagram. “Some options need early modules; others can remain open longer. We can explore a potential Minor too, but only if its complete 40-ECTS structure is viable later.”`,options:[opt('“I have a possible Major, but I want to compare options.”','fa4',{form:{confidence:'leaning',minor:'undecided'}}),opt('“I’m genuinely undecided and want to explore.”','fa4',{form:{confidence:'exploring',minor:'undecided'}}),opt('“I might want a Minor as well.”','fa4',{form:{confidence:'exploring',minor:'interested'}})]},
 fa4:{place:'east',speaker:'Julie · academic adviser',portrait:'adviser',title:'The practical side of choice',text:`“Now, is there anything about the timetable or your circumstances we should think about?” Julie asks. “You don't need to explain anything private. But if there are travel, work or caring commitments, it helps to know which aspects of a proposed schedule might be difficult.”\n\nYou remember the timetable screenshot you saw at induction. Six modules might look straightforward on paper, but classes could be spread across the week.`,options:[opt('“I commute and need to plan transport.”','faBreadth',{form:{constraint:'commuting'}}),opt('“I have work or caring commitments to plan around.”','faBreadth',{form:{constraint:'time commitments'}}),opt('“No specific constraint, but I need to understand independent study.”','faBreadth',{form:{constraint:'workload questions'}})]},
 faBreadth:{place:'east',speaker:'Julie · academic adviser',portrait:'adviser',title:'Breadth is part of your degree too',text:`“One more thing before we finish,” says Julie. “Arts is not built solely around the Major. The Spine is shared learning, and SARs introduce you to other areas. You might discover something you never thought you would study.”\n\n“What would you be interested in exploring outside your main subjects?”`,options:[opt('“Society, sustainability and the environment.”','fa5',{form:{sar:'Sustainability and society'}}),opt('“Communication, culture and languages.”','fa5',{form:{sar:'Culture and languages'}}),opt('“I’m open to exploring something unfamiliar.”','fa5',{form:{sar:'Open to different SAR areas'}})]},
 fa5:{place:'east',speaker:'Julie · academic adviser',portrait:'adviser',title:'What would you like clarified?',text:s=>`Julie summarises what she has recorded so far. “I have your interests, where you are in your thinking and the practical issue you raised. What do you want us to check first?”\n\nThis is where a good question makes a difference. There is no prize for appearing to know the answers already.`,options:[opt('“What should I take early to keep my possible Major open?”','fa6',{form:{question:'Which early modules could protect my preferred Major?'}}),opt('“How do I know which modules I have actually been allocated?”','fa6',{form:{question:'How can I distinguish preferences, allocations and registration?'}}),opt('“Can we check if my interests fit with an optional Minor?”','fa6',{form:{question:'Could a compatible Minor be viable later?'}}),opt('“How will 30 ECTS fit around my week?”','fa6',{form:{question:'What does 30 ECTS mean for time and workload?'}})]},
 fa6:{place:'east',speaker:'Julie · academic adviser',portrait:'adviser',title:'A useful next step',text:s=>`“That's worth checking,” says Julie. She explains that advising can record possible Major and Minor directions, pathway watch points and next steps. She cannot guarantee that a requested module has a place or timetable slot. Any proposed module combination must be checked against the current programme information, availability and registration processes.\n\nShe asks you to choose what to do after this meeting.`,options:[opt('“I’ll review the actual planner and follow up on requirements.”','faDone',{form:{completed:true,followup:'Check possible Major requirements and the real Curriculum Planner with my adviser.'}}),opt('“I’ll compare the proposed sessions with my commitments and ask about conflicts.”','faDone',{form:{completed:true,followup:'Check the example timetable and ask the programme team about any actual allocation problems.'}})]},
 faDone:{place:'east',speaker:'Narrator',title:'Your advising record and practice timetable',text:s=>`The meeting ends with a short summary: your current interests, your uncertainty or confidence, a practical watch point and an agreed action. Julie calls it your first advising record.\n\nWhen you open the in-game phone, you find a fictional practice timetable built from the interests you discussed. The programme has not registered you for anything. The made-up timetable is there so you can learn to compare classes, study hours and pathway options without affecting a university record.\n\nTry the timetable on your phone. Notice where the classes are, what isn't shown and why an adviser would need to check real capacity and sequencing before confirming a plan.`,options:[opt('Open my new practice timetable','practiceTimetable',{done:'formA',note:'Form A records the advising discussion, not module choices or registration. The example timetable is only a simulation.'}),opt('Return to campus and review my advising record','practiceForm',{done:'formA'})],chapterEnd:1},

 /* Mission 1: registration + appropriate routing */
 missing1:{place:'central',speaker:'Cian · fellow student',portrait:'peer',title:'The Missing Module',text:"It's the first week of teaching, and the buildings are beginning to feel a little less unfamiliar. You have found your way to Central Quad, although you still have to check the signs every time you leave a room. During induction, everyone talked about the freedom of the Arts programme: different subjects, possible Majors, and the chance to discover interests you hadn't expected. That sounded exciting. It also sounded much simpler when somebody was explaining it from a stage.\n\nYou sit on a low wall and open your timetable for the third time today. Most of the modules look familiar, but one subject you ranked highly when you submitted your preferences is nowhere to be seen. You remember putting it near the top of your list. You also remember mentioning it at your first advising conversation. You assumed that meant you would be taking it.\n\nCian, another first-year you've met twice but already recognise across campus, drops their bag beside you. “Are you still checking that thing? Mine's packed. There's a gap on Thursday, but every other day looks different.” Cian leans closer to inspect your screen. “Wait. Didn't you say you were doing that subject?”\n\nYou explain that it isn't there. Cian frowns, then shrugs. “Maybe the system's just late. Somebody in our group chat said you can turn up to the lecture and they’ll sort it. I thought we were meant to choose everything ourselves.” You remember the adviser saying something about availability, though you can't remember the exact words. You don't want to make a fuss over nothing. On the other hand, you had hoped to explore this subject before deciding what direction to take.\n\nCian looks up. “So what are you going to do?”",options:[opt('“But I definitely put it near the top of my list.”','missing2',{flag:{moduleAssumption:'preference'}}),opt('“I might be mixing up what I asked for with what I got.”','missing2',{flag:{moduleAssumption:'question'}}),opt('“Could I just go to the first class and ask?”','missing2',{flag:{moduleAssumption:'turnup'}})]},
 missing2:{place:'central',speaker:'Cian · fellow student',portrait:'peer',title:'A confident suggestion',text:s=>s.flags.moduleAssumption==='turnup'?'Cian nods. “That’s what I was thinking. But someone in our group chat said a lecturer can’t just add you to the official module list.” You are no longer sure that turning up will solve it.':s.flags.moduleAssumption==='preference'?'Cian shrugs. “I thought the same. I’ve heard some classes are capped, though. Maybe ranking a module and actually getting a place aren’t the same.”':'Cian looks relieved. “That’s what I’m trying to figure out. There must be someone who can check the official position.”',options:[opt('Go to programme support to check the allocation','missingOps'),opt('Find an academic adviser to discuss what it means for your pathway','missingAdv')]},
 missingOps:{place:'rathdown',speaker:'Niamh · student support colleague',portrait:'support',title:'Checking the record',text:'“Tell me what you expected to see and what is showing now. We can establish whether this is a registration or allocation question. If the problem affects your academic pathway, the programme advising team may also need to be involved.”',options:[opt('“Can you guarantee me the place?”','missingOpsGuarantee'),opt('“How can I tell when the module is actually confirmed?”','missingOpsConfirm')]},
 missingOpsGuarantee:{place:'rathdown',speaker:'Niamh · student support colleague',portrait:'support',title:'No informal guarantees',text:'“I can help you find out what is recorded, but I cannot promise a place without confirmation of capacity and the registration process. Let’s check what the programme team has confirmed.”',options:[opt('Ask what you should do next','missingResolve')]},
 missingOpsConfirm:{place:'rathdown',speaker:'Niamh · student support colleague',portrait:'support',title:'Preference is not registration',text:'“Look for formal registration confirmation, rather than relying on the preference form, a conversation or somebody else’s timetable. If the module is missing, the appropriate team needs to check it.”',options:[opt('Ask what you should do next','missingResolve')]},
 missingAdv:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'Your options are bigger than one module',text:'“Let’s check whether the missing module is simply an interest, or whether it helps keep an intended Major viable. We can discuss alternatives, but I can’t allocate a place or override a capacity restriction.”',options:[opt('“I’m unsure what I want to Major in.”','missingAdvExplore'),opt('“I’m worried this affects a future Major.”','missingAdvProtect')]},
 missingAdvExplore:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'Room to explore',text:'“That’s expected in Stage 1. We can identify several possibilities and look for an introductory mix that preserves options where possible.”',options:[opt('Agree to check the official registration and alternative choices','missingResolve')]},
 missingAdvProtect:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'A question worth checking early',text:'“Some pathways depend on an early module sequence or eligibility check. We should find out if this one does, then raise any registration problem through the appropriate route.”',options:[opt('Agree to check the pathway and registration separately','missingResolve')]},
 missingResolve:{place:'central',speaker:'Narrator',title:'A useful distinction',text:'You now know why a preference, an advised choice and a registered module are different. The question is being directed to the right people; it is not magically resolved by the conversation.',options:[opt('Save your findings and tackle a new case','followMissing1',{done:'missing',note:'Module preferences do not guarantee registration. Check official confirmation; ask your adviser about pathway implications and programme support about allocation/registration.',contact:'Academic adviser',message:['My TU Dublin','Tip added: preferences are not confirmed registrations.']})]},
 /* Mission 2: exploratory breadth and gateway */
 path1:{place:'east',speaker:'Saoirse · classmate',portrait:'peer',title:'Something Unexpected',text:"It's the end of an introductory session in East Quad. You had only come because it appeared in the list of subjects you could explore, and you didn't know quite what else to expect. The room was lively. The lecturer showed examples from several disciplines and invited people to argue about how they might approach the same question. You had more to say than you expected.\n\nOutside the classroom, students spill into the bright corridor. Some seem to know precisely what they want from the degree. Others are comparing modules, swapping room numbers and discovering that their timetables barely overlap. You feel a small rush of excitement: perhaps there is more here for you than the two subjects you wrote on your application.\n\nSaoirse, who sat beside you, catches up. “That was actually great,” she says. “I didn't think I'd like it either.” You agree, then wonder how this new interest fits with the subjects you already had in mind. If you keep adding possibilities, will you eventually have to give something up?\n\nSaoirse asks, almost casually, “So what are you going to Major in?” You start to say the subject you'd originally imagined, then stop. For the first time, you're less certain. You say, “I don't really know yet,” and hear yourself apologising as though you have failed a test. Saoirse laughs. “Neither do I. Everyone keeps asking, though.”\n\nYou still have the rest of your first year to explore, but you're beginning to suspect that some choices might matter earlier than others. How do you respond?",options:[opt('“Maybe I should just pick one now and stop thinking about it.”','path2',{flag:{pathAttitude:'rush'}}),opt('“I want to try a few things before deciding — if that\'s possible.”','path2',{flag:{pathAttitude:'explore'}})]},
 path2:{place:'east',speaker:'Saoirse · classmate',portrait:'peer',title:'A competing interest',text:'Saoirse says she is also interested in Computer Science, but heard that some Majors need you to start particular modules in first year. She isn’t sure what is true, and neither are you.',options:[opt('Go and check the pathway guidance with an adviser','pathAdv',{flag:{pathAction:'check'}}),opt('Decide you can sort everything out much later','pathDelay',{flag:{pathAction:'delay'}})]},
 pathAdv:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'Exploration with some structure',text:'“You do not have to formally commit to a Major in your first weeks. However, certain possible pathways need early attention. Computer Science and Food & Nutrition are examples where Stage 1 activity can matter. We should check the approved requirements rather than assume.”',options:[opt('“So can I keep more than one option alive?”','pathOptions')]},
 pathOptions:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'Protecting realistic options',text:'“Often yes, subject to prerequisites, capacity and timetable fit. We can map what you are interested in and flag any early conditions. A pathway preference later in Stage 1 is still indicative; formal Major confirmation comes later.”',options:[opt('Make a note and continue exploring','pathFinish',{flag:{pathway:'checked'}})]},
 pathDelay:{place:'east',speaker:'Narrator',title:'You leave the question open',text:'You decide to enjoy exploring for now. That can be valuable. But you still have an unanswered question about whether particular subject sequences should begin this semester. Nothing has closed yet; you may need to investigate before it does.',options:[opt('Keep exploring','pathFinish',{flag:{pathway:'unverified'}})]},
 pathFinish:{place:'east',speaker:'Narrator',title:'The direction is yours to explore',text:'An exploratory first year has a purpose. The useful skill is learning which decisions can wait and which need timely advice.',options:[opt('Try the pathway planning follow-up','followPathway1',{done:'pathway',note:'Stage 1 is exploratory, but some Majors have early prerequisites, sequences or gateway checks. Indicative preference is not formal Major confirmation.',contact:'Academic adviser'})]},
 /* Mission 3 workload */
 work1:{place:'library',speaker:'Saoirse · classmate',portrait:'peer',title:'Two Empty Days',text:"Monday morning. Your phone alarm goes off at the same time it did in school, but you have no class to travel to. Tuesday is blank as well. At first, you wonder whether the timetable has failed to load. You refresh it, close it, and open it again. Nothing changes.\n\nLater, you meet Saoirse near the Academic Hub & Library. She is carrying a coffee and complaining about having to cross campus between two classes. You show her the empty days. “Two days off?” she says. “You're joking. Mine is packed!” She starts comparing timetables on her phone. You recognise some of the same module titles, but the pattern of classes is completely different.\n\nYou remember hearing that university modules have credits attached to them. You've seen '5 ECTS' written beside several subjects, but nobody has sat beside you and explained what that might mean for a normal week. You know there will be reading and assignments; you're just not sure how to fit them into days that don't look like school days.\n\nA notification arrives from one of your modules: reading for next week's discussion, a small task to prepare and a reminder to check the online learning space. There's also a social event you wanted to attend this afternoon. You could use the spare time to settle into the city, take on more work shifts, or begin preparing for classes. Perhaps there's a problem with the timetable after all.\n\nSaoirse grins. “Well, what are you doing with your two days off?”",options:[opt('“No lectures, no work — I’m calling them days off.”','work2',{flag:{workStyle:'unplanned'}}),opt('“I should probably check what I’m meant to do outside class.”','work2',{flag:{workStyle:'plan'}}),opt('“First I want to make sure this timetable is actually right.”','work2',{flag:{workStyle:'verify'}})]},
 work2:{place:'library',speaker:'Aoife · lecturer',portrait:'lecturer',title:'What does a module involve?',text:s=>s.flags.workStyle==='unplanned'?'Aoife notices that you have not opened the reading list. “There’s a lot of learning outside the classroom,” she says. “How are you using the gaps?”':s.flags.workStyle==='verify'?'Aoife suggests you confirm the timetable through the official route, then explains that timetables show scheduled learning rather than all study hours.':'Aoife looks at your draft study plan. “Good start. A timetable tells you when classes take place, not every hour you need for reading, practice and assignments.”',options:[opt('“Does 5 ECTS mean only five hours?”','workCredits'),opt('“How can I prepare for the first assessment?”','workAssess')]},
 workCredits:{place:'library',speaker:'Aoife · lecturer',portrait:'lecturer',title:'Credit and workload',text:'“ECTS reflects the total student workload required for learning, not just class contact. Look at each module descriptor and its expected activities. Different modules can have quite different weekly patterns.”',options:[opt('Ask about putting a weekly plan together','workPlan')]},
 workAssess:{place:'library',speaker:'Aoife · lecturer',portrait:'lecturer',title:'Assessment is approaching',text:'“Start with the brief and its learning outcomes. Find the submission date, ask about any unclear instructions, and use the library and academic writing supports if needed.”',options:[opt('Ask about a weekly plan','workPlan')]},
 workPlan:{place:'library',speaker:'Narrator',title:'Time you can choose to use',text:'The blank days are still blank on your timetable. But now you recognise they can hold reading, writing, practice, paid work, commuting or rest. You need a realistic plan that fits your circumstances.',options:[opt('Try planning a real week','followWorkload1',{done:'workload',note:'Class hours are only part of university workload. Check module descriptors and assessment briefs; use gaps realistically.',contact:'Module lecturer',flag:{workKnowledge:true}})]},
 /* Mission 4 Student Hub / institutional responsibility */
 support1:{place:'rathdown',speaker:'Niamh · student support colleague',portrait:'support',title:'Who Actually Helps?',text:"By your second week, your phone contains more university emails than you know what to do with. One message mentions registration; another directs you to a School; a third says to ask the programme team. You have also heard someone refer to the Student Hub and somebody else tell you to contact an academic adviser. The names are beginning to blur together.\n\nYou follow signs towards Rathdown House. The older building feels very different from the new teaching spaces. Inside, several students are waiting: one needs help with a student card, another is talking about an online account, and a third is trying to explain why something on their record looks wrong. You realise you aren't the only person still finding their feet.\n\nNiamh, a member of the student-support team in this fictional story, waves you forward. “Hi. What can I help you with?” You begin with the timetable question you've been carrying around. Halfway through explaining, you remember something else: a friend told you they were struggling to attend because of difficulties at home. You are also wondering whom you would speak to if something personal began affecting your own classes.\n\nNiamh listens, but doesn't pretend all these issues have the same solution. “We can work out where the question belongs,” she says. “Sometimes the first useful thing is finding the right person.” You have a choice about where to begin the conversation.",options:[opt('“Can we start with the timetable and registration?”','supportRoute'),opt('“What if something outside university is affecting my attendance?”','supportWellbeing')]},
 supportRoute:{place:'rathdown',speaker:'Niamh · student support colleague',portrait:'support',title:'The route depends on the problem',text:'“For an official registration or record query, start with the appropriate administrative support. If you need to understand the academic consequences of a module change, contact your academic adviser. For what happens inside a particular class, the module lecturer is often the right person.”',options:[opt('“What if each person sends me to someone else?”','supportEscalate'),opt('“Can you explain the difference again?”','supportRepeat')]},
 supportRepeat:{place:'rathdown',speaker:'Niamh · student support colleague',portrait:'support',title:'Three kinds of question',text:'“A lecturer explains their module. An adviser helps with academic pathway decisions. Administration establishes what is officially recorded and routes operational matters. Some problems involve more than one of them.”',options:[opt('Ask how to keep track of the query','supportEscalate')]},
 supportEscalate:{place:'rathdown',speaker:'Niamh · student support colleague',portrait:'support',title:'Make the issue legible',text:'“Say what happened, what you have checked, and what you need clarified. Keep a record of the response. If the academic problem remains unresolved, your adviser can help identify the appropriate review or escalation route.”',options:[opt('Save the contact guidance','supportFinish',{flag:{supportRoute:true}})]},
 supportWellbeing:{place:'rathdown',speaker:'Niamh · student support colleague',portrait:'support',title:'Support beyond module choice',text:'“It might help to speak to the Student Health Centre, counselling, disability support or another relevant service. You can ask for confidential guidance without explaining everything to a module lecturer or an academic adviser first.”',options:[opt('“And what about an academic deadline?”','supportDeadline')]},
 supportDeadline:{place:'rathdown',speaker:'Niamh · student support colleague',portrait:'support',title:'Two things may be needed',text:'“A specialist support service can advise on the personal situation. You may also need to follow the published academic procedure for assessment or attendance issues. Support services do not automatically change programme rules.”',options:[opt('Save the support information','supportFinish',{flag:{supportRoute:true}})]},
 supportFinish:{place:'rathdown',speaker:'Narrator',title:'You have more than one kind of support',text:'You leave with a clearer sense that different people have different responsibilities. Getting help is a skill, and university processes may require coordination rather than a single quick answer.',options:[opt('Try a more complicated support request','followSupport1',{done:'support',note:'Match the question to the role: lecturer for module teaching, adviser for pathway implications, administration for official records, and specialist services for personal support.',contact:'Student Hub and specialist supports'})]},
 /* Mission 5 belonging */
 belong1:{place:'lower',speaker:'Rory · society organiser',portrait:'leader',title:'The Invitation',text:"You have a gap between classes and no particular destination. For the first time since induction, you walk towards Lower House without needing to check your timetable. There is noise from a common room, a few people playing games, and a noticeboard crowded with posters. You pause by one advertising music, film, volunteering and society events.\n\nSo far, you've recognised faces without quite knowing names. A few people seem to have settled into groups already. You tell yourself you don't really need to join anything; there is enough to figure out with the modules. But you also remember spending most of the previous evening scrolling through messages rather than talking to anyone.\n\nRory, a student society organiser, notices you reading the posters. “Thinking of joining something?” Rory asks. “There's no audition to come to the first meeting, if that's what you're wondering.” They point towards a gathering later in the week. A handful of students are talking nearby, and one waves as if you might already be part of the group.\n\nYou don't know if you'll have time. You're not even sure whether you have the right interests. Rory adds, “People join to try things out, too. You don't have to be good at it already.” Their tone is friendly, but you still feel awkward about walking into a room where everyone might know one another.\n\nRory waits while you decide whether to ask a question, leave, or raise something else that's been worrying you.",options:[opt('“What actually happens at one of these meetings?”','belongAsk'),opt('“I might come back another time.”','belongLeave',{flag:{social:'hesitant'}}),opt('“Can the Students’ Union help if I’m worried about something?”','belongUnion')]},
 belongAsk:{place:'lower',speaker:'Rory · society organiser',portrait:'leader',title:'No experience required',text:'“Come along and see whether you like it. You don’t have to commit to every event. If you’re new, that’s exactly why you might enjoy it.”',options:[opt('Ask if you can bring a classmate','belongFriend'),opt('Ask how to find other activities','belongUnion')]},
 belongFriend:{place:'lower',speaker:'Rory · society organiser',portrait:'leader',title:'A low-pressure start',text:'“Of course. And you can just turn up and listen if you prefer.” You decide the next event might be worth trying.',options:[opt('Save the event for later','belongEnd',{flag:{social:'connected'}})]},
 belongUnion:{place:'lower',speaker:'Rory · society organiser',portrait:'leader',title:'Student voice',text:'“The Students’ Union is also about representation and advocacy, not only clubs and events. It can help students navigate concerns and connect with the wider student community.”',options:[opt('Add that to your contacts','belongEnd',{flag:{social:'informed'}})]},
 belongLeave:{place:'lower',speaker:'Narrator',title:'Maybe another time',text:'You head back towards class. You haven’t made a mistake. But you now know there are opportunities beyond your modules, and you can revisit them when it suits you.',options:[opt('Return to campus','belongEnd')]},
 belongEnd:{place:'lower',speaker:'Narrator',title:'A different kind of connection',text:'The social side of the university is part of the experience too. Your route into it can be gradual and on your own terms.',options:[opt('See what happens a few weeks later','followBelonging1',{done:'belonging',note:'Lower House has student common spaces and society activity. The Students’ Union supports representation and student voice as well as community involvement.',contact:'Students’ Union and societies'})]},
 /* Mission 6 assessment / learning spaces */
 assess1:{place:'library',speaker:'Aoife · lecturer',portrait:'lecturer',title:'The First Assignment',text:"It's the second week and the excitement of starting university is giving way to something more practical: actual assignments. A notification arrives from the online learning space while you're sitting in the library. It contains a brief with a deadline, a list of learning outcomes and several instructions you think you understand — until you try to picture what the finished work is supposed to look like.\n\nThe task is shorter than you expected, but it asks you to use evidence and respond to a particular question. You scroll past the marking criteria, then back up to read them again. You are used to being told exactly what to produce. Here, you seem to be expected to make more decisions yourself.\n\nA group chat lights up. Someone says they've already finished. Another student asks whether references are needed. A third shares a screenshot of a half-written response. You feel suddenly behind, even though the assignment was only released today. You consider copying the structure of what somebody else has done, but you don't know whether it would actually address your own brief.\n\nAoife, one of your lecturers, is nearby speaking with another student. She seems approachable, although also busy. You could ask her what the task requires. You could first read the criteria properly or find the library's study support. Or you could start writing and hope the expectations become clearer as you go.\n\nYou open a blank document. The cursor flashes. What is your first move?",options:[opt('“I’ll just start writing. I’ll figure the brief out as I go.”','assess2',{flag:{assessment:'rush'}}),opt('“Before anything else, I’m reading the brief and criteria again.”','assess2',{flag:{assessment:'inspect'}}),opt('“Maybe someone can send me what they’ve written so far.”','assess2',{flag:{assessment:'copyrisk'}})]},
 assess2:{place:'library',speaker:'Aoife · lecturer',portrait:'lecturer',title:'Understanding the task',text:s=>s.flags.assessment==='copyrisk'?'Aoife says, “Talking through ideas with peers can help, but submitting another person’s work or using it inappropriately could create academic-integrity problems. Let’s understand the task in your own words.”':s.flags.assessment==='rush'?'Aoife asks, “Have you checked what is being assessed? Starting early is useful, but writing before understanding the brief can send you in the wrong direction.”':'Aoife says, “You’ve started with the right documents. Which part of the brief is still unclear?”',options:[opt('“Who can explain the assessment criteria?”','assessExplain'),opt('“Where can I get help with writing and research?”','assessSupport')]},
 assessExplain:{place:'library',speaker:'Aoife · lecturer',portrait:'lecturer',title:'Ask the module team',text:'“I can explain the requirements and marking criteria. Keep an eye on the module learning outcomes and the instructions. Asking questions is part of the process.”',options:[opt('Find out about wider learning supports','assessSupport')]},
 assessSupport:{place:'library',speaker:'Narrator',title:'Learning support exists',text:'The library offers study spaces and learning resources. The Academic Writing & Learning Centre is another point of support. Your lecturer remains the right person for assessment-specific instructions and criteria.',options:[opt('Note the support options','assessEnd')]},
 assessEnd:{place:'library',speaker:'Narrator',title:'A better starting point',text:'You still have to do the assignment, but you know how to interpret the task, where to clarify requirements and how to seek appropriate help.',options:[opt('Try the assessment follow-up','followAssessment1',{done:'assessment',note:'For assessment, check the brief, learning outcomes and criteria. Ask the lecturer about task requirements; seek academic writing and library support for skills.',contact:'Academic Writing & Learning Centre'})]},

 /* New v0.9 encounter: interpreting a published timetable change */
 change1:{place:'east',speaker:'Cian · fellow student',portrait:'peer',title:'The Timetable Changed',text:"You leave a session at East Quad and glance at your phone. A new timetable notification has arrived. You are certain you had a tutorial on Tuesday morning, because you wrote it in your notebook during induction. But the message says something has changed since the last publication.\n\nCian is standing by the doors, staring at a similar message. ‘It says one class has moved and another isn't showing. How are we supposed to know which version is right?’ Cian shows you a screenshot saved from last week. The old and new schedules don't match.\n\nYou have a job shift later in the week and you want to plan your travel, so you need the current version. You remember seeing a blue changes box above the weekly timetable, but you skipped past it because the grid looked easier to read.\n\nThe message doesn't necessarily mean a module has disappeared from your registration. It could be a particular class activity that has changed. Before making arrangements, you need to work out what the update actually says.",options:[opt('Open the phone timetable and read the changes since publication','changeCheck',{flag:{timetableApproach:'check'},note:'Published timetable changes should be read alongside the latest weekly grid.'}),opt('Use the screenshot from last week: it was correct then','changeOld',{flag:{timetableApproach:'old'}}),opt('Ask Cian whether you should simply attend the old slot','changeSam',{flag:{timetableApproach:'peer'}})]},
 changeOld:{place:'east',speaker:'Cian · fellow student',portrait:'peer',title:'Last week’s screenshot',text:'Cian looks from the saved image to your phone. “But that screenshot is from before the update. If a class has moved, we could end up at the wrong room or miss it entirely.” You decide to compare the two versions rather than assume the old one still applies.',options:[opt('Open the latest timetable and investigate','changeCheck')]},
 changeSam:{place:'east',speaker:'Cian · fellow student',portrait:'peer',title:'A second opinion',text:'“I’m not sure either,” says Cian. “I think the changes box is meant to tell us exactly what moved. It probably makes more sense to check that first.” You realise that comparing guesses is not the same as checking the published schedule.',options:[opt('Read the published timetable change','changeCheck')]},
 changeCheck:{place:'east',speaker:'Narrator',title:'Read the update, then the grid',text:'You open My Timetable on your phone. The blue change summary names the activity that moved from Tuesday to Wednesday, while a Friday workshop has been added. The weekly grid underneath reflects the latest published position.\n\nYou still need to distinguish a changed class meeting from a change to the module itself. You can check which module is registered in your curriculum profile, and you can raise a query if the change leaves you uncertain about attendance or your study plan.',options:[opt('Check whether my modules are still in the curriculum profile','changeProfile',{flag:{changeRead:true}}),opt('Ask the right team what the timetable update means','changeSupport',{flag:{changeRead:true}})]},
 changeProfile:{place:'east',speaker:'Julie · academic adviser',portrait:'adviser',title:'Classes and module records are different',text:'“A timetable change may affect a particular class without altering the module you are registered on. The curriculum profile helps you understand your current build; the latest timetable tells you when activities are scheduled. If something is still inconsistent, raise it through the appropriate programme process.”',options:[opt('Apply this in a fresh timetable problem','followTimetable1',{done:'timetable',contact:'Programme operations / timetable queries',note:'A change to an individual class does not automatically mean that the whole module registration has changed.'})]},
 changeSupport:{place:'rathdown',speaker:'Niamh · student support colleague',portrait:'support',title:'Where to raise a timetable query',text:'“Keep the exact module, day and class activity to hand. The programme team can check allocation and timetable concerns. The lecturer can explain the teaching activity, and your adviser can help if the timetable creates a pathway problem.” You now know what information to provide when asking for help.',options:[opt('Apply this in a fresh timetable problem','followTimetable1',{done:'timetable',contact:'Programme operations / timetable queries',note:'When reporting a timetable issue, give the module, activity, day and the published change.'})]},

 /* Mission 8: the first-cohort misunderstanding, and behavioural transfer */
 explore1:{place:'central',speaker:'Cian · fellow student',portrait:'peer',title:'Exploring Is Not Swapping',text:"It's a bright afternoon in the second week. You are sitting near Central Quad when Cian appears holding two coffees and a new idea. Yesterday a visiting lecturer described a subject Cian had never considered. Now Cian wants to take it. The problem is that it isn't among the six modules on the timetable.\n\n‘This is the whole point of Arts, isn't it?’ Cian says. ‘They told us first year is for exploring. So surely we can switch things around until we find what we like.’\n\nYou remember the welcome presentation. You heard the same message: try different areas, keep an open mind, don't rush into declaring a Major. But you also remember submitting preferences, getting an allocated set of modules, and being told to check what you were registered on. There is a difference somewhere, and the language used during induction didn't make it especially clear.\n\nCian has already drafted a message to the lecturer: ‘Hi, I'm joining your class tomorrow.’ You can see why Cian thinks it makes sense. University is meant to offer more freedom than school. Still, if students could simply swap each week, how would classes, capacity and progression work?\n\n‘What would you do?’ Cian asks. You have the real Arts Hub and Curriculum Planner shortcuts on your in-game phone, a practice timetable, and a route to an adviser conversation. Decide how to approach this before making a promise to Cian.",options:[opt('“I think exploration means I can change a registered module whenever I want.”','exploreSwap',{flag:{explorationAssumption:'freeSwap'}}),opt('“We can explore interests, but I’d check how registration changes work.”','exploreInvestigate',{flag:{explorationAssumption:'check'}}),opt('“I’d rather not say anything; it probably sorts itself out.”','exploreIgnore',{flag:{explorationAssumption:'avoid'}})]},
 exploreSwap:{place:'central',speaker:'Cian · fellow student',portrait:'peer',title:'An appealing interpretation',text:'“Exactly!” Cian says, and starts typing. But another student nearby says they tried switching a module informally and were told their registration hadn’t changed. Cian pauses. “So I could be attending something I’m not registered for?” The question is more complicated than it appeared. You can still explore the new subject. You need to distinguish an interest from an approved module change.',options:[opt('Open the practice Curriculum Planner to check my current build','exploreProfile',{flag:{plannerConsulted:true}}),opt('Arrange a conversation with the adviser','exploreBooking',{flag:{requestedAdvice:true}})]},
 exploreIgnore:{place:'central',speaker:'Narrator',title:'The question does not disappear',text:'You say you are not sure. Cian sends the message to the lecturer anyway. Two days later, Cian hears that attending a class and being registered on its module are different things. You still have time to find out how to explore the subject properly, but leaving the question unanswered has not solved it.',options:[opt('Investigate the options with Sam','exploreInvestigate')]},
 exploreInvestigate:{place:'central',speaker:'Cian · fellow student',portrait:'peer',title:'What does my actual record say?',text:'You compare your original preference list with the modules showing on your timetable. The difference is clearer now: a preference helps the programme understand what you want, while a registered module is the formal record. You can discuss interests and potential future pathways throughout Stage 1. If you want to alter an existing registration, that is a separate request and must go through the approved process.\n\nCian says, “I still want to explore this new subject. I just need to know whether I could take it now, next semester, or as part of a later pathway.” You can examine your current build in the practice planner, or set up a meeting to discuss the possibilities.',options:[opt('Inspect the current build in the practice planner','exploreProfile',{flag:{plannerConsulted:true}}),opt('Ask to meet an academic adviser','exploreBooking',{flag:{requestedAdvice:true}})]},
 exploreProfile:{place:'central',speaker:'Narrator',title:'Six modules, thirty credits',text:s=>`Your example Curriculum Planner profile lists six registered modules totalling 30 ECTS for Semester 1. The subjects you might want to study in the future are displayed separately as interests and possible pathways. ${s.flags.plannerConsulted?'You have checked the practice build rather than relying on a conversation alone.':''}\n\nThere is no button here that makes an informal swap official. The planner can help you understand your current record and investigate consequences; the programme's approved processes determine any real change. You can now arrange an adviser discussion about future possibilities.`,options:[opt('Arrange a fictional advising appointment through the phone','exploreBooking',{flag:{plannerConsulted:true}}),opt('I think I understand — move to the Week 3 consequence','exploreConsequences',{flag:{plannerConsulted:true,explorationAction:'independent'}})]},
 exploreBooking:{place:'central',speaker:'Narrator',title:'Book a conversation',text:'You use the phone to request a conversation. In this practice game, it creates a message and an appointment in the story; it does not contact a real TU Dublin staff member. Cian asks whether you can both come. You want to ask about the new subject, any prerequisite sequences and whether changing this semester’s registration is even possible.',options:[opt('Book the practice appointment and meet Julie','exploreMeeting',{appointment:true,flag:{explorationAction:'advice'}}),opt('Check the learning guides first','exploreGuidance',{flag:{explorationAction:'guidance'}})]},
 exploreGuidance:{place:'library',speaker:'Narrator',title:'Read the distinction',text:'The Arts Hub guidance explains the programme structure and the role of academic advising. Stage 1 is exploratory because students can discover interests and prepare future pathways. That does not mean the registered timetable is a menu students can alter without approval. The process for any change depends on the programme rules, timing, capacity, prerequisites and formal registration. You jot down the difference, then make a plan to discuss the new interest.',options:[opt('Take that question to the adviser','exploreMeeting',{appointment:true,flag:{guidanceRead:true}}),opt('See how it plays out in Week 3','exploreConsequences',{flag:{guidanceRead:true,explorationAction:'guidance'}})]},
 exploreMeeting:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'A conversation about choice',text:s=>`Julie listens to Cian’s idea and asks what has prompted the change. “That’s exactly the kind of curiosity we hope Stage 1 encourages,” she says. “But we need to separate three things: exploring an interest, planning a possible Major, and altering a registered module.”\n\nYou show the example current build and explain the new subject. “We can look at future opportunities, prerequisites and which options need protection. If a module change is being requested now, we need to check the appropriate formal route, availability and consequences. Neither an adviser conversation nor attending an extra lecture changes a registration on its own.”\n\n${s.flags.plannerConsulted?'You can refer to the six modules you checked in the planner, which makes the discussion more precise.':'You realise that looking at the curriculum profile before the meeting would have helped you describe your current position.'} Cian puts the phone away. “So I can change my mind about where I’m heading without quietly changing what I’m already enrolled on.”`,options:[opt('Ask what Cian could do next','exploreOutcome',{flag:{explorationAction:'advice',differenceUnderstood:true}}),opt('Ask whether a new Major can require an early module','exploreGateway',{flag:{explorationAction:'advice',differenceUnderstood:true}})]},
 exploreGateway:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'What can wait — and what cannot?',text:'“Some Major options need an early module sequence, eligibility check or specialist approval. That is why keeping future options open sometimes means taking action now. We need to check the actual approved pathway and current availability, rather than promise you can start any subject at any time.”',options:[opt('Ask about the appropriate next step','exploreOutcome',{flag:{gatewayDiscussed:true}})]},
 exploreOutcome:{place:'central',speaker:'Cian · fellow student',portrait:'peer',title:'A workable plan',text:'Cian decides to keep attending the modules on the confirmed timetable while investigating whether the newly discovered subject could become a later option. If a formal change is sought, it will be considered through the approved process. Nobody has promised that a place is available. But an interest that surfaced in Week 2 can still shape future advising and module choices.\n\nThe point is easier to understand now than it was in the induction talk: exploratory study gives you room to discover direction; registered modules and approved changes still have formal rules.',options:[opt('Continue to Week 3 and test what I learned','exploreConsequences',{flag:{differenceUnderstood:true}})]},
 exploreConsequences:{place:'lower',speaker:'Cian · fellow student',portrait:'peer',title:'Week 3: The same misunderstanding returns',text:s=>`A few days later another student says: “I love a module my friend takes. I might just drop my registered class and start theirs on Monday. It’s exploration year, after all.” Cian looks at you.\n\n${s.flags.explorationAction==='advice'?'You remember Julie distinguishing future possibilities from registered modules.':s.flags.plannerConsulted?'You remember the six-module build you checked in your practice planner.':'You recognise this is the same dilemma you encountered earlier.'}\n\nThe new student is enthusiastic, and you do not want to put them off trying something different. What advice would you give?`,options:[opt('“Try the class first. Sorting registration can wait.”','exploreReview',{flag:{transferAnswer:'attend'}}),opt('“Explore it, but check your current registration and get advice before requesting any change.”','exploreReview',{flag:{transferAnswer:'check'}}),opt('“You’re not allowed to change interests once the semester starts.”','exploreReview',{flag:{transferAnswer:'closed'}})]},
 exploreReview:{place:'lower',speaker:'Narrator',title:'What travels beyond the game',text:s=>s.flags.transferAnswer==='check'?'You have distinguished an academic interest from a registration decision. The other student can explore the subject through guidance and a conversation, and enquire about a formal change where possible. They should not assume that attendance or a preference changes the official record.':s.flags.transferAnswer==='attend'?'The other student risks attending a class without formal registration or missing required activities in their registered modules. Exploration is encouraged, but a change needs to be checked and approved through the appropriate process.':'You have treated the registered timetable as fixed forever, but the student can still explore interests and ask whether a change is possible through an approved process. The programme rules set the conditions; the answer is not automatically yes or no.',options:[opt('Try a fresh exploration question','followExploration1',{done:'exploration',note:'Stage 1 exploration is about discovering interests and preparing viable pathways. Changing a registered module is a separate formal process, not an automatic right to swap.',contact:'Academic adviser · exploring and checking pathway implications',flag:{explorationCompleted:true}})]},
 /* Mission 9: getting ready for academic advising */
 prep1:{place:'library',speaker:'Narrator',title:'The Meeting Tomorrow',text:"You've been at TU Dublin long enough to recognise a few faces, but not long enough to feel completely sure how everything works. An invitation to an academic advising meeting appears on your phone. The message asks you to think about your interests, the modules you're taking and any questions you'd like to raise. You put the phone down, then pick it up again.\n\nYou've got plenty of questions, but they're muddled together. You enjoyed a creative module more than expected, you're still curious about Computer Science, and you aren't sure why the subject you ranked third never appeared on your timetable. Someone in your group chat says advisers can change your modules during a meeting; someone else says the meeting is where you have to choose your Major forever. Neither sounds quite right.\n\nThe meeting is tomorrow. You could arrive and explain everything as it comes to mind, or spend a few minutes finding out what information would make the conversation useful. Your in-game phone has a practice timetable, a Curriculum Planner profile and an Arts Hub. What do you do first?",options:[opt('Open my timetable and current module build','prepRecord',{flag:{prepRecord:true}}),opt('Write down the subjects I am interested in and why','prepInterests',{flag:{prepInterests:true}}),opt('Go straight to the meeting and see what happens','prepMeeting',{flag:{prepWalkIn:true}})]},
 prepRecord:{place:'library',speaker:'Narrator',title:'What is actually on your record?',text:"The example timetable shows six Semester 1 modules. The Curriculum Planner shows your current module build and possible Major interests in different sections. You notice that the module you wanted is not among the registered modules. That doesn't automatically tell you why, and it doesn't mean the adviser can simply add it.\n\nYou make a note: 'My preferred module is missing. Does this matter for the directions I'm considering?' Next, you could think about your academic interests, or go to the meeting and talk through what you've found.",options:[opt('Write down my interests and questions','prepInterests',{flag:{prepInterests:true}}),opt('Attend the meeting with my timetable details','prepMeeting')]},
 prepInterests:{place:'lower',speaker:'Saoirse · classmate',portrait:'peer',title:'What do you want from the conversation?',text:s=>`Saoirse finds you making notes near the student spaces in Lower House. “I’ve an advising meeting too,” she says. “I thought I was meant to arrive with a Major already picked.”\n\nYou tell her that you've enjoyed subjects you didn't expect and are thinking about possible directions. She asks what you'd actually like to know. You begin a list: which subjects you might explore next, whether anything must be taken early to preserve a Major option, how a Minor might fit, and who can resolve the missing module. ${s.flags.prepRecord?'Because you checked your timetable, you can name the specific issue without guessing.':'You realise you have not yet checked the exact modules appearing in your current timetable.'}\n\nSaoirse nods. “So I can go in with questions, not a final answer.” You agree. But the list is getting long. Which question should lead the meeting?`,options:[opt('“Could you help me protect two possible Major pathways?”','prepMeeting',{flag:{prepQuestion:'pathways'}}),opt('“Can I change my registered module this week?”','prepMeeting',{flag:{prepQuestion:'change'}}),opt('“I’m not sure what the adviser can actually help with.”','prepMeeting',{flag:{prepQuestion:'role'}})]},
 prepMeeting:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'Your advising conversation',text:s=>`Julie welcomes you and asks how the first weeks are going. There isn't a test or a requirement to announce your future Major. This is a conversation about where you are now and what needs checking.\n\n${s.flags.prepRecord?'You open your practice timetable and can point to the modules currently listed. Julie is able to distinguish a possible registration issue from a question about your academic direction.':'You mention a module you think is missing, but cannot remember the code or whether you were actually registered. Julie suggests checking the current timetable and planner together before treating it as a confirmed problem.'}\n\n${s.flags.prepInterests?'You can explain the subjects you enjoyed, what surprised you, and the two directions you might want to preserve. Julie asks about prerequisites and what you might need to investigate before the next advising point.':'When asked about your interests, you struggle to put them into words. Julie gives you space to think and suggests making a short list after the meeting. You have not missed your chance to explore.'}\n\n${s.flags.prepQuestion==='change'?'You ask whether you can swap modules now. Julie explains that an interest or an advising discussion does not change formal registration; any request has to be checked through the approved programme process.':s.flags.prepQuestion==='pathways'?'You ask how to keep two routes viable. Julie suggests checking the relevant early modules, gateways and conditions, rather than promising either route will remain available.':s.flags.prepQuestion==='role'?'You ask which questions belong to an adviser. Julie describes academic pathway guidance and explains where registration and administrative questions need to go.':'Julie asks which issue feels most urgent and helps you turn a general worry into questions to investigate.'}\n\nBefore you leave, Julie asks what you will do next.`,options:[opt('Agree three practical follow-up actions','prepActions',{flag:{prepFollowUp:'three'}}),opt('Leave and hope the meeting resolves everything','prepLater',{flag:{prepFollowUp:'none'}})]},
 prepLater:{place:'central',speaker:'Narrator',title:'After the meeting',text:"Outside Central Quad, you feel better for having talked things through. But when you check your phone later, you cannot quite remember what was agreed. Your timetable hasn't automatically changed, and you still want to explore the same subjects. A useful conversation needs a little follow-through. You open the Notes app and try again to identify the next steps.",options:[opt('Make a practical follow-up list','prepActions',{flag:{prepFollowUp:'recovered'}})]},
 prepActions:{place:'central',speaker:'Narrator',title:'An advising plan you can use',text:s=>`You put three items in your phone notes. First: verify the modules currently recorded for you, and ask the appropriate team if something is wrong. Second: check the requirements or early sequences for possible Majors, rather than assuming every option will remain available. Third: note the decisions and deadlines you need to return to at the next advising checkpoint.\n\n${s.flags.prepRecord&&s.flags.prepInterests?'Because you brought your current build and academic interests into the conversation, the follow-up tasks feel specific and manageable.':'You realise that next time it would help to arrive with your current timetable and a short list of questions. The adviser can still support you; preparation simply makes the time more productive.'}\n\nYou haven't made a final Major decision, and you haven't changed a registered module. You have left with a clearer plan and know how to seek further help.`,options:[opt('Save my preparation checklist to the phone','prepTransfer',{flag:{prepChecklist:true},note:'Before advising: check my current timetable and Curriculum Planner; list my interests and questions; identify possible gateway/prerequisite issues; clarify who needs to action a registration query; record follow-up tasks and dates.',contact:'Academic adviser · pathway planning and follow-up'})]},
 prepTransfer:{place:'lower',speaker:'Saoirse · classmate',portrait:'peer',title:'A small favour for Saoirse',text:"Later, Saoirse messages you. Her own meeting is next week. 'I still don't know what Major I want,' she writes. 'I suppose I'll just turn up and let the adviser decide.' You recognise the anxiety in the message. You also know an adviser shouldn't have to make the choice for her. What would you suggest she does before going?",options:[opt('“Bring your timetable and a few genuine questions. You don’t need a final Major decision.”','prepResolve',{flag:{prepTransfer:'prepared'}}),opt('“Pick a Major tonight so you can tell them the answer.”','prepResolve',{flag:{prepTransfer:'premature'}}),opt('“They’ll have all the answers. You don’t need to think about anything.”','prepResolve',{flag:{prepTransfer:'passive'}})]},
 prepResolve:{place:'lower',speaker:'Narrator',title:'What the meeting is for',text:s=>s.flags.prepTransfer==='prepared'?'Saoirse thanks you. She checks the planner and writes down what she has enjoyed, what she is worried about, and what she wants to ask. Her adviser will still need to check the official rules and current options, but the meeting can now start from her real concerns.':s.flags.prepTransfer==='premature'?'Saoirse becomes more anxious because she feels she has to make a final commitment before understanding the options. Stage 1 advising is intended to support exploration; an indicative preference should not be confused with formal Major confirmation.':'Saoirse arrives unable to explain what interests her or which modules she is taking. The adviser can help her start, but the meeting would have been more useful with a few questions and a look at her current record.',options:[opt('Try a follow-up after advising','followPreparation1',{done:'preparation',flag:{preparationCompleted:true},note:'An advising session is a conversation. Bring current registration details, possible interests and specific questions; leave with agreed next steps. It does not automatically change module registration.'})]},

 /* Guided story: seven short chapters, traversable in induction, not real-time */
 ch0a:{place:'central',speaker:'Narrator',title:'Your story so far',text:s=>`Tomorrow you start BA Arts at TU Dublin. You have a phone full of messages, directions to Grangegorman and a handful of subjects that sound interesting. Some people around you seem certain about their future. Others are still deciding what they want to explore.\n\nBefore the first class, you find yourself remembering how you learned before university. Your earlier experiences might help in some situations and mislead you in others. What kind of learning are you used to?`,options:[opt('A school timetable and regular teacher reminders','ch0b',{flag:{past:'school'}}),opt('Work, further education or returning to study','ch0b',{flag:{past:'other'}}),opt('A mixture, and I am not sure what university expects','ch0b',{flag:{past:'mixed'}})]},
 ch0b:{place:'central',speaker:s=>`Older ${s.name} · a possible future`,title:'Four years later?',text:s=>`For a moment, you imagine standing in Grangegorman on graduation day. Someone asks what your first year was like. You try to picture an answer, but there are too many things that might happen between now and then.\n\n${s.flags.past==='school'?'You remember having a full school day planned for you. University may expect more decisions about how and when you study.':s.flags.past==='other'?'You have previous experiences of managing your time independently. University may still introduce unfamiliar rules and assessment routines.':'Your experience gives you a mixture of habits and expectations. You may need to figure out what transfers well.'}\n\nThis is a possible future, not a prediction. The screen slips back to your first morning at TU Dublin.`,options:[opt('Begin induction at Grangegorman','hub',{note:'University may feel different from earlier learning. You can ask questions, investigate systems and build useful habits.'})],chapterEnd:0},
 welcomePaul:{place:'east',meeting:'welcome',speaker:paul,title:welcome.title,text:welcome.text,
  options:welcome.choices.map((label,i)=>opt(label,'welcomePaulReply',{flag:{welcomeConcern:i===0?'arrival':'subjects'}}))},
 welcomePaulReply:{place:'east',meeting:'welcome',speaker:paul,title:'A question to bring to Julie',
  text:s=>welcomeReply(s.flags.welcomeConcern),
  options:[opt('Find Julie outside East Quad','ch1a')]},
 ch1a:{place:'east',speaker:'Julie · Academic Adviser',portrait:'adviser',title:'What have I joined?',
  text:s=>`${s.flags.welcomeConcern==='subjects'?'“Paul said you had a question about Music,” Julie says. “What drew you to it in the first place?” You tell her you wanted to try a subject you’d never had a chance to study. She asks what else you’d like to keep open.':'Julie waves you over. “Before we get into modules, what were you hoping Arts would give you a chance to try?” You name one subject, then add another that seems quite different. “Can I do both?”'}

“You can explore more than one area in Stage 1. Let’s look at what has to fit into a four-year, 240 ECTS degree. There’s an approved Major, 30 credits of common Spine modules and 50 credits of Subject Area Requirements. A Minor takes 40 credits if you choose to take one. Any room for Free Electives depends on the rest of the degree you build.”

She pulls up an example. “We can move the pieces around first. Then we can talk about what you’d actually like me to record.”`,
  options:[opt('Open the degree builder','ch1b')]},
 ch1b:{place:'east',speaker:'Julie · academic adviser',portrait:'adviser',title:'Build a possible degree',text:s=>`Your example currently has a ${s.flags.degreeMajor||80} ECTS Major and ${s.flags.degreeMinor?'a 40 ECTS Minor':'no Minor'}. The Spine is mandatory at 30 ECTS and SARs account for 50 ECTS of breadth across eight areas.\n\nA bigger Major can leave less room for other choices. But a calculation alone cannot tell you whether the combination is approved, whether prerequisites are met or whether the timetable works. Your adviser and current programme information remain important.\n\nChoose a different example to see how the balance changes.`,options:[opt('Try an 80 ECTS Major, no Minor','ch1c',{flag:{degreeMajor:80,degreeMinor:false}}),opt('Try a 100 ECTS Major and 40 ECTS Minor','ch1c',{flag:{degreeMajor:100,degreeMinor:true}}),opt('Try a 120 ECTS Major and 40 ECTS Minor','ch1c',{flag:{degreeMajor:120,degreeMinor:true}})]},
 ch1c:{place:'east',speaker:'Julie · academic adviser',portrait:'adviser',title:'What can you choose?',text:s=>`You have explored the arithmetic of an example degree. ${s.flags.degreeMajor===120?'A 120 ECTS Major plus a 40 ECTS Minor would use all 240 credits alongside the required General Education components. There would be no separate Free Elective space. Viability would still require formal checking.':'There may be credit space for further modules, depending on your approved Major, any Minor and the General Education requirements.'}\n\nYou ask whether you have to declare a Major now. “Not now,” Julie says. “Stage 1 is exploratory, but some paths have early prerequisites, eligibility checks or capacity constraints. You will submit an indicative pathway preference during Stage 1, while formal Major confirmation comes later in Stage 2.”\n\nYou leave knowing that exploration is about discovering academic directions, within an organised degree.`,options:[opt('Start a practice Form A advising conversation','fa1',{note:'BA Arts: four-year 240 ECTS degree; 60 ECTS per year; 30 ECTS Spine + 50 ECTS SARs; approved Major (80–120 ECTS); optional 40 ECTS Minor; Free Electives depend on available credits. Pathway viability needs official checking.',flag:{degreeLearned:true}})]},
 ch2a:{place:'central',speaker:lecturer,portrait:'lecturer',title:'Your first module',
  text:lecturerIntro+'\n\nBefore you go, she shows you a sample module page. It sets out what you should learn, how the work is assessed, the credits and the classes and study the module involves. What would you check first?',
  options:[opt('Read the module descriptor and assessment information','trailStart',{flag:{moduleChecked:true}}),
   opt('Assume only the scheduled classes count as work','trailStart',{flag:{moduleAssumption:'contact'}}),
   opt('Ask how much work I should expect between classes','trailStart',{flag:{moduleAssumption:'ask'}})]},
 trailStart:{place:'bradogue',sign:'bradogue',speaker:'Campus trail',title:campusTrail[0].title,text:campusTrail[0].text,
  options:campusTrail[0].observations.map(o=>opt(o.label,'ch2b',{trail:{id:'bradogue',note:o.note}}))},
 ch2b:{place:'library',speaker:'Library study adviser',portrait:'support',title:'What does 5 ECTS mean?',text:s=>`You investigate the workload guide. Credits represent total expected learning effort, which includes time in class, reading, projects, practice, assessment and independent study. At TU Dublin, a 5 ECTS module represents an estimated 100 hours of total student effort, including classes, reading, practice, independent study and assessment. Assessment is included in those hours, not added on top; it is not five class hours.\n\n${s.flags.moduleAssumption==='contact'?'You now see why a timetable with gaps is not necessarily a light academic workload.':'The learning hours make more sense once you separate scheduled contact from independent study.'}\n\nYou open a sample module descriptor. It lists learning outcomes and assessment components. You realise that studying at university means organising the time between classes, not waiting to be given something to do each day.`,options:[opt('Plan one study block around the next assignment','ch2c',{flag:{studyPlan:true}}),opt('I will work things out as deadlines arrive','ch2c',{flag:{studyPlan:false}})]},
 ch2c:{place:'east',speaker:'Narrator',title:'Your first two weeks',text:s=>`A timetable notification arrives. A seminar has moved, but that does not automatically mean your registered modules have changed. A friend says you can attend any class that interests you. You remember that academic curiosity and module registration are separate things.\n\n${s.flags.studyPlan?'You also have a study block in your calendar. It is not a guarantee that everything will go smoothly, but it gives you time to begin.':'You still have not decided when to work on the upcoming assignment. The choice will come back when the deadline approaches.'}\n\nThe game phone contains a practice timetable and a Curriculum Planner. Neither changes your actual TU Dublin record.`,options:[opt('Continue into Weeks 3–4','hub',{note:'ECTS represent total expected learning effort, not class hours alone. A module has learning outcomes and assessed work. Use the official module descriptor and current timetable to plan.'})],chapterEnd:2},
 ch3a:{place:'lower',speaker:'Cian · fellow student',portrait:'peer',title:'I thought Stage 1 meant I could change anything',text:`At Lower House, Cian tells you about a class they enjoyed. “I'm thinking of dropping something from my timetable and going to that instead. They said first year is for exploring, didn't they?”\n\nYou remember the phrase too. The programme encourages students to discover interests, and the opportunity to explore is part of the reason you chose BA Arts. But something about Cian's plan worries you. The timetable shows registered modules, and other subjects may have prerequisites or limited places.\n\nHow would you respond without telling Cian to abandon an interesting subject?`,options:[opt('Explore the subject, but check the official route before changing registration','ch3b',{flag:{swapResponse:'check'}}),opt('Tell Cian to attend the new class instead and sort paperwork later','ch3b',{flag:{swapResponse:'turnup'}}),opt('Say exploration means never changing direction','ch3b',{flag:{swapResponse:'never'}})]},
 ch3b:{place:'rathdown',speaker:'Programme support',portrait:'support',title:'Exploration has boundaries',text:s=>`${s.flags.swapResponse==='turnup'?'Cian later discovers that attending a class is not the same as being formally registered on its module.':'You and Cian investigate what the words on the programme guidance actually mean.'}\n\nStage 1 allows academic exploration and opportunities to keep future Major options open. It does not permit unilateral changes to registered modules. Changes may be possible through authorised processes, subject to timetable, capacity, prerequisites, suitability and other requirements.\n\nOn your way out you notice a societies noticeboard and a student event. The semester also holds possibilities beyond administrative questions.`,options:[opt('Follow the invitation to an arts society','ch3c',{flag:{positiveDiscovery:'society'}}),opt('Visit the library and discover an unfamiliar subject','ch3c',{flag:{positiveDiscovery:'library'}})]},
 ch3c:{place:'lower',speaker:'Jordan · student representative',portrait:'union',title:'An unexpected connection',text:s=>s.flags.positiveDiscovery==='society'?`You attend a small society event and meet students interested in performance, design and sustainability. Someone tells you about a project that brought music, visual media and community activity together. You don't have to choose it as a Major to appreciate the connection.\n\nYou leave with a contact and a possible idea for later. Making friends and finding a sense of belonging can happen gradually; one event is not a test.`:`Browsing the library's exhibitions and resources, you find a student project combining visual culture, sustainability and digital storytelling. The subject area is new to you, but it makes sense in the context of an Arts degree designed for breadth and connections.\n\nYour academic interests may change. Exploring an idea is useful even when it doesn't become a module or Major.`,options:[opt('Continue into the assessment weeks','hub',{note:'Stage 1 exploration is about discovering and protecting possible pathways. Changing registered modules requires the approved process; keep exploring subjects and student opportunities.',contact:'Students’ Union and societies · belonging and activities'})],chapterEnd:3},
 ch4a:{place:'library',speaker:'Narrator',title:'A deadline is approaching',text:s=>`It is Week 6 and an assignment is due. You have a brief, a marking rubric and a date on the module page. You also have your first experience of deciding how to work without someone checking every day.\n\n${s.flags.studyPlan?'You recognise the study time you set aside earlier, but the assignment still needs care.':'You recall postponing your study plan. Now the deadline is closer than you expected.'}\n\nA memory of your earlier learning appears: at school or in a previous course, someone often reminded you what came next. Here the lecturer expects you to read the requirements and manage the work. Which action would help most?`,options:[opt('Read outcomes and rubric, then map the remaining work','ch4b',{flag:{assessmentStrategy:'plan'}}),opt('Start writing immediately without looking at the marking criteria','ch4b',{flag:{assessmentStrategy:'rush'}}),opt('Ask for clarification about what the brief requires','ch4b',{flag:{assessmentStrategy:'clarify'}})]},
 ch4b:{place:'east',speaker:'Ms Ní Chonaill · module lecturer',portrait:'lecturer',title:'Assessment and feedback',text:s=>`${s.flags.assessmentStrategy==='plan'?'You align your work with the learning outcomes and marking criteria and submit it through the specified system.':'You submit the assignment, but discover that the marking criteria cover elements you did not fully address.'}\n\nA module can use continuous assessment, examinations, practical work, projects or combinations approved in its descriptor. Marks from different assessment elements contribute according to the approved assessment scheme, and some elements may have special pass requirements. Feedback is intended to help you learn what is working and what needs improvement.\n\nYour practice result appears. It is below the pass standard in this fictional scenario. You feel disappointed. What do you do next?`,options:[opt('Read the feedback, check the regulations and ask what reassessment options apply','ch4c',{flag:{failureResponse:'check'}}),opt('Assume failing this assessment means losing the whole year','ch4c',{flag:{failureResponse:'panic'}}),opt('Ignore the result for now; maybe it will disappear','ch4c',{flag:{failureResponse:'ignore'}})]},
 ch4c:{place:'library',speaker:'Narrator',title:'A setback is not the end of the story',text:s=>`${s.flags.failureResponse==='check'?'You investigate what the assessment result actually means.':'You discover that a disappointing mark needs checking rather than an assumption about the entire year.'}\n\nFailing one assessment and failing a module are not always the same thing. Your module's approved assessment scheme, pass requirements and TU Dublin assessment regulations determine the result and what happens next. Depending on the case, reassessment or other provisions may apply, but they must never be assumed or guaranteed by the game. Formal progression decisions are also governed by university rules.\n\nYou seek feedback and make a concrete plan to improve your next submission. A short flash-forward shows you working on a later project with more confidence. You do not know the outcome of the real future, but you can see how responding to feedback may matter.`,options:[opt('Save the assessment lesson and continue','hub',{note:'Check each module descriptor for outcomes, assessment components, deadlines and any special pass requirements. One failed assessment is not automatically a failed module. Use official TU Dublin regulations and staff advice for results, reassessment and progression.',flag:{assessmentLearned:true}})],chapterEnd:4},
 ch5a:{place:'library',speaker:'Narrator',title:'You have an advising meeting tomorrow',text:`An email arrives in Week 9 asking you to prepare for an academic advising conversation. You have become interested in more than one direction, a module on your current timetable is not what you originally preferred, and you're wondering what will matter for Stage 2.\n\nYou could arrive with vague questions or spend a few minutes gathering the information that only you can bring: what has interested you, what has been difficult, and what you want to understand.`,options:[opt('Review my current build and write two questions','ch5b',{flag:{meetingPrepared:true}}),opt('Go to the meeting and explain what comes to mind','ch5b',{flag:{meetingPrepared:false}})]},
 ch5b:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'Where might you go next?',text:s=>`${s.flags.meetingPrepared?'You show Julie your current modules, your ranked interests and two specific questions. The conversation quickly turns to the requirements of possible pathways.':'Julie helps you work through your interests and suggests opening the current planner together. You can still have a productive meeting without having everything organised in advance.'}\n\nYou talk about a possible Major and an optional Minor. Julie distinguishes an indicative Stage 1 preference from formal Major confirmation later in Stage 2. She explains why certain pathways need earlier preparation and why availability and timetable constraints still apply.\n\nAt the end, she asks what you will do after the meeting.`,options:[opt('Record the questions, owner and next steps in my phone','ch5c',{flag:{meetingFollowUp:true}}),opt('Assume the discussion changes my registration automatically','ch5c',{flag:{meetingFollowUp:false}})]},
 ch5c:{place:'central',speaker:'Narrator',title:'Leaving with a plan',text:s=>`${s.flags.meetingFollowUp?'You save the actions you agreed: check a pathway requirement, review the real Curriculum Planner and follow up through the right office if a registration detail is wrong.':'You realise that an advising conversation does not itself change registered modules or settle every programme decision. You add a short follow-up list before leaving.'}\n\nYour interests are still developing. That is appropriate at this stage. The useful outcome is knowing which options need checking, where the reliable information lives, and when formal decisions are due.`,options:[opt('Continue toward the end of semester','hub',{note:'Before advising: check the real Curriculum Planner and timetable; note interests, concerns and specific questions. Afterward: write down who will do what, by when. A conversation does not itself change registration.',contact:'Academic Adviser · academic pathway planning'})],chapterEnd:5},
 ch6a:{place:'lower',speaker:'Cian · fellow student',portrait:'peer',title:'An unfamiliar problem',text:`It is almost the end of Semester 1. Cian has heard that a student from another class wants to switch to a new subject after enjoying a guest lecture. They are worried that not selecting it now will close every future opportunity.\n\nCian asks you what advice to offer. No lecturer or adviser is present to supply an answer. You have learned about interests, registration, prerequisites, the planner and the different forms of support. What would you suggest?`,options:[opt('Check the pathway and prerequisites, then discuss feasible options with an adviser','ch6b',{flag:{transfer:'informed'}}),opt('Tell them to change classes informally so they do not miss out','ch6b',{flag:{transfer:'swap'}}),opt('Tell them never to explore anything outside their current timetable','ch6b',{flag:{transfer:'restrict'}})]},
 ch6b:{place:'central',speaker:'Narrator',title:'A possible graduation',text:s=>`${s.flags.transfer==='informed'?'You find a way to preserve curiosity while checking the academic and administrative conditions. Cian can see how the university systems and people work together.':'Cian asks whether the advice would actually work. You reconsider: academic exploration can be encouraged, but official registration and pathway rules still matter.'}\n\nFour years flash forward. You imagine returning to Grangegorman for graduation. You remember some of the subjects you never expected to enjoy, the friends you made, the setbacks that taught you to ask better questions and the advisers and staff who helped along the way. It is one possible future, not a promise.\n\nLooking back, what would you tell the student who arrived on the first day?`,options:[opt('“Explore widely, check what matters, and ask for help early.”','ch6c',{flag:{futureMessage:'explore'}}),opt('“A setback can be a moment to learn what to do next.”','ch6c',{flag:{futureMessage:'recover'}}),opt('“The degree is more than a timetable of classes.”','ch6c',{flag:{futureMessage:'degree'}})]},
 ch6c:{place:'central',speaker:'Narrator',title:'Back to the first day',text:`The image of graduation fades, and you're back at induction. You haven't lived through the semester yet. You have practised how to investigate it.\n\nYou know the basic Arts degree structure, how a module and ECTS work, why a timetable doesn't show all your study time, what academic exploration means, how assessments and feedback fit together, and how to use the Arts Hub, Curriculum Planner and university contacts.\n\nThere are plenty of things you will still need to look up. That is part of being a university student. This story has given you a starting point, not a replacement for official programme guidance.`,options:[opt('See my story reflection','ending',{flag:{guidedFinished:true},note:'I completed the guided semester story. My next move is to explore the real Arts Hub and Curriculum Planner and prepare questions for induction.'})],chapterEnd:6},

 /* v1.3: Transfer encounters — a fresh situation after the first problem, not a quiz. */
 followMissing1:{place:'central',speaker:'Cian · fellow student',portrait:'peer',title:'Week 3: another module, another question',text:s=>`Cian meets you after class. “I got an email about an introductory module I really wanted, but it still does not appear in my current build. The lecturer was friendly and said I could come along to see what it was like. Surely that means I am enrolled?”\n\nYour own first-week query ${s.flags.moduleAssumption==='turnup'?'started with a similar assumption. You now know that attendance and registration can be separate.':'taught you to distinguish interest, availability and the official record.'} This time Cian wants to make a decision before tomorrow morning.`,options:[opt('Ask Cian to show the confirmed module build and message','followMissingEvidence',{flag:{missingTransfer:'evidence'}}),opt('Tell Cian to go to class and worry about records later','followMissingShortcut',{flag:{missingTransfer:'shortcut'}})]},
 followMissingEvidence:{place:'central',speaker:'Cian · fellow student',portrait:'peer',title:'What can the message prove?',text:'Cian shows you the email. It invites students to an open introductory talk. It says nothing about a confirmed allocation. “Right. That is a chance to find out about the subject,” Cian says, “but not proof I can claim credits for it.” They ask how to find out what is possible next.',options:[opt('Work out a precise enquiry together','followMissingEnd',{flag:{missingInvestigation:true}})]},
 followMissingShortcut:{place:'east',speaker:'Saoirse · classmate',portrait:'peer',title:'An invitation is not a registration',text:'Saoirse has seen the same invitation. “That is a taster session,” she says. “You can still enjoy it. But someone needs to confirm what is actually registered.” Cian is annoyed that the distinction was not obvious. You can help them check rather than make them feel foolish.',options:[opt('Help Cian separate exploration from enrolment','followMissingEnd',{flag:{missingInvestigation:false}})]},
 followMissingEnd:{place:'central',speaker:'Narrator',title:'An enquiry that can be answered',text:s=>`${s.flags.missingInvestigation?'Together you list the module code, the published allocation, the exact message and the possible pathway concern.':'You decide to check the official build before making any promises.'}\n\nCian asks: “What should I actually write?” This is your chance to choose what to request, not simply whom to ask.`,options:[opt('Ask programme support to check allocation; ask advising about future pathway implications','hub',{flag:{missingFollowup:'separated'},note:'Follow-up case: distinguish an invitation, a registered module and a pathway question; include the module code and ask the correct teams.'}),opt('Ask the lecturer to guarantee a place and update my credits','hub',{flag:{missingFollowup:'unresolved'},note:'Follow-up case: a lecturer invitation cannot replace formal allocation or registration; revisit the appropriate route.'})]},

 followPathway1:{place:'east',speaker:'Saoirse · classmate',portrait:'peer',title:'Week 6: the subject you did not expect',text:'A guest workshop brings together students interested in music, digital media and sustainability. You enjoy it, and Saoirse notices. “You did not even have that on your original list,” she says. “I have been thinking of a different Major myself. But what if the introductory sequence is already underway?”\n\nThere is an exciting new direction here, although nobody has yet checked whether it can become an approved Major or Minor.',options:[opt('Explore the new interest and compare official one-pagers','followPathwayCompare',{flag:{pathTransfer:'compare'}}),opt('Decide that changing interests is too risky','followPathwayClose',{flag:{pathTransfer:'close'}})]},
 followPathwayCompare:{place:'library',speaker:'Saoirse · classmate',portrait:'peer',title:'Two interests on the table',text:'You pull up the programme guidance. One area has a possible introductory sequence. Another has a different credit pattern. Neither can be confirmed from a single attractive workshop. Saoirse says, “So we can be curious without promising ourselves a pathway we have not checked?”',options:[opt('Identify the points you need to confirm with advising','followPathwayEnd',{flag:{pathEvidence:true}})]},
 followPathwayClose:{place:'east',speaker:'Cian · fellow student',portrait:'peer',title:'Keeping curiosity open',text:'Cian remembers enjoying an unexpected subject too. “You do not have to turn every interesting class into your Major,” he says. “But there is no harm in finding out what a pathway would involve.” Your choice to narrow down early is yours; you can still look into the opportunity.',options:[opt('Check how an interest could fit into the degree','followPathwayEnd',{flag:{pathEvidence:false}})]},
 followPathwayEnd:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'A pathway is more than a title',text:s=>`“Tell me what you enjoy about both areas,” Julie says. ${s.flags.pathEvidence?'You arrive with a comparison of the introductory requirements.':'You describe the workshop and the direction you are considering.'} She asks which aspect matters most: developing disciplinary depth, exploring a secondary interest or taking a module for breadth.`,options:[opt('Compare Major, optional Minor and SAR possibilities without changing registration','hub',{flag:{pathFollowup:'compared'},note:'Follow-up case: enthusiasm for a subject can lead to Major, Minor, SAR or elective exploration; check each against current rules and sequencing.'}),opt('Ask to be declared in the new Major immediately','hub',{flag:{pathFollowup:'premature'},note:'Follow-up case: Stage 1 preferences are indicative; check formal confirmation timing and pathway eligibility.'})]},

 followWorkload1:{place:'library',speaker:'Saoirse · classmate',portrait:'peer',title:'Week 5: two deadlines on Friday',text:'You open the module pages. Two 5 ECTS modules both have work due on Friday. You also have paid work on Wednesday evening and a planned family visit on Sunday. The timetable still looks quiet, but these commitments will not complete themselves.\n\nA 5 ECTS module represents 100 hours of total learning effort, including teaching, independent learning and assessment. It does not require 100 additional hours on top of the assessments.',options:[opt('Write down each deadline, remaining task and available study block','followWorkloadPlan',{flag:{workTransfer:'plan'}}),opt('Leave both tasks until Thursday because the timetable is quiet','followWorkloadRush',{flag:{workTransfer:'rush'}})]},
 followWorkloadPlan:{place:'library',speaker:'Narrator',title:'The hours become visible',text:'Once you list the tasks, you see the work is uneven. One submission needs research and drafting; the other needs preparation for a short presentation. You can protect study time now and leave space for rest. Saoirse asks what you will do if one task takes longer than expected.',options:[opt('Build a buffer and check expectations with the module teams','followWorkloadEnd',{flag:{workBuffer:true}})]},
 followWorkloadRush:{place:'library',speaker:'Narrator',title:'Thursday gets crowded',text:'On Thursday evening you open the briefs and realise one assignment requires research you have not begun. The other includes a group contribution. You cannot undo the timing, but you can still prioritise, communicate and check the support available.',options:[opt('Look at the briefs and make an achievable plan for what remains','followWorkloadEnd',{flag:{workBuffer:false}})]},
 followWorkloadEnd:{place:'library',speaker:'Aoife · lecturer',portrait:'lecturer',title:'Planning is not a personality test',text:s=>`${s.flags.workBuffer?'Aoife sees that you have allowed time for reading, drafting and checking your work.':'Aoife helps you identify what is essential, what needs clarification and what support may still help.'} “You are planning total learning effort,” she says, “not counting only lecture hours.”\n\nA friend suggests asking for an extension by simply not submitting. You know there must be a better way to find out about arrangements.`,options:[opt('Check the published assessment guidance and ask promptly about any genuine difficulty','hub',{flag:{workFollowup:'informed'},note:'Follow-up case: 5 ECTS = 100 hours total, including assessment. Plan across modules; check official assessment and extension procedures rather than assume.'}),opt('Assume silence will be treated as an extension','hub',{flag:{workFollowup:'unresolved'},note:'Follow-up case: non-submission is not an agreed extension; use the current official process and seek help early.'})]},

 followSupport1:{place:'rathdown',speaker:'Niamh Ní Chonaill · student support colleague',portrait:'support',title:'Week 4: one email, three problems',text:'A student called Róisín is overwhelmed. Their timetable shows a class at the wrong time; they are worried about missing a prerequisite; and they have been having trouble settling in. They have written one long email to several people and received three different replies.\n\nNiamh asks, “If Róisín were sitting here, how might you help them separate what needs a programme decision from what needs personal support?”',options:[opt('Separate the academic record, pathway and wellbeing concerns','followSupportMap',{flag:{supportTransfer:'separate'}}),opt('Tell Róisín to keep emailing everyone until somebody fixes it','followSupportAll',{flag:{supportTransfer:'broadcast'}})]},
 followSupportMap:{place:'rathdown',speaker:'Niamh Ní Chonaill · student support colleague',portrait:'support',title:'Three routes, one student',text:'Together you identify who can help with the published timetable and allocation, who can advise on the possible pathway and where Róisín can seek confidential personal support. No one route has to solve all three. Niamh asks how you will prevent Róisín having to repeat the story unnecessarily.',options:[opt('Write concise facts, requested action and agreed next steps','followSupportEnd',{flag:{supportFollowupDraft:true}})]},
 followSupportAll:{place:'rathdown',speaker:'Niamh Ní Chonaill · student support colleague',portrait:'support',title:'Lots of replies, little clarity',text:'“When the same question is sent to several teams, people can unintentionally give conflicting answers,” Niamh explains. “That is not Róisín’s fault, but we can help identify a lead contact for each issue.” The aim is to reduce confusion, not to send a student away.',options:[opt('Help Róisín organise the questions by responsibility','followSupportEnd',{flag:{supportFollowupDraft:false}})]},
 followSupportEnd:{place:'central',speaker:'Narrator',title:'A useful follow-up',text:s=>`${s.flags.supportFollowupDraft?'Róisín leaves with three short questions and a note about who is following up.':'You help Róisín identify a first contact for each issue.'} The personal issue is treated confidentially. The timetable problem still requires an authoritative check; the pathway question still needs academic advice.`,options:[opt('Follow up with the appropriate team and check whether actions were completed','hub',{flag:{supportFollowup:'owned'},note:'Follow-up case: triage timetable, pathway and personal-support issues separately; record a clear owner and next step.'}),opt('Assume the referral itself means all three issues are fixed','hub',{flag:{supportFollowup:'unverified'},note:'Follow-up case: referral is not resolution; check agreed actions and avoid circulating sensitive personal details.'})]},

 followBelonging1:{place:'lower',speaker:'Saoirse · classmate',portrait:'peer',title:'Week 4: somebody new in the room',text:'You are back near Lower House. A small group is planning a campus event. A mature student called Bríd stands in the doorway. She commutes, has family commitments and does not know if the group would suit her. Saoirse says, “We are heading over for twenty minutes. I wonder if she would come?”\n\nYou remember your own first invitation. You also know that students find their place in different ways.',options:[opt('Invite Bríd without assuming she can stay all evening','followBelongingInvite',{flag:{belongTransfer:'invite'}}),opt('Assume a busy commuter would not want to join','followBelongingAssume',{flag:{belongTransfer:'assume'}})]},
 followBelongingInvite:{place:'lower',speaker:'Bríd · fellow student',portrait:'peer',title:'A way to take part',text:'“I can stay for a bit,” Bríd says. “I would like to know what else happens on campus — I just cannot always make the evening things.” The group suggests a short lunchtime meet-up next week. Nothing dramatic happens, but it opens a door.',options:[opt('Help find a time and format that works for more people','followBelongingEnd',{flag:{belongAccessible:true}})]},
 followBelongingAssume:{place:'lower',speaker:'Bríd · fellow student',portrait:'peer',title:'An assumption worth checking',text:'Bríd overhears the group and asks what is happening. She is interested — just not in a late-night event. You realise that social connection is not one-size-fits-all; asking is more useful than making a decision on somebody else’s behalf.',options:[opt('Offer the information and let Bríd decide','followBelongingEnd',{flag:{belongAccessible:false}})]},
 followBelongingEnd:{place:'lower',speaker:'Narrator',title:'Belonging on different terms',text:'A few students meet again in daylight. One joins a society, one volunteers on a project and another prefers a small study group. Their experiences do not have to look alike. Your role was to make an invitation possible, not prescribe a university social life.',options:[opt('Keep the invitation open and respect individual preferences','hub',{flag:{belongFollowup:'inclusive'},note:'Follow-up case: make low-pressure, accessible invitations without assuming age, transport, family commitments or confidence.'}),opt('Decide that everyone should attend the same events','hub',{flag:{belongFollowup:'narrow'},note:'Follow-up case: belonging can include societies, study groups, projects and informal daytime connections.'})]},

 followAssessment1:{place:'library',speaker:'Aoife · lecturer',portrait:'lecturer',title:'Week 7: feedback arrives',text:'You have submitted a practice assignment. The online module space shows written feedback: your ideas were interesting, but the argument was hard to follow and some sources were missing. Saoirse says, “At least it is over.”\n\nThe feedback relates to stated learning outcomes and assessment criteria. There is another activity later in the module. What do you do with these comments?',options:[opt('Compare feedback with the brief and draft a question for Aoife','followAssessmentReview',{flag:{assessTransfer:'review'}}),opt('Put it away; the first mark is all that matters','followAssessmentAvoid',{flag:{assessTransfer:'avoid'}})]},
 followAssessmentReview:{place:'library',speaker:'Aoife · lecturer',portrait:'lecturer',title:'A useful conversation about feedback',text:'“Show me where the reasoning became difficult to follow,” Aoife asks. You compare the marking criteria with a paragraph of your work. “I can explain the standard and point you towards writing support,” she says. “You will need to make the revisions yourself.”',options:[opt('Plan one specific improvement for the next task','followAssessmentEnd',{flag:{assessPrepared:true}})]},
 followAssessmentAvoid:{place:'library',speaker:'Saoirse · classmate',portrait:'peer',title:'The next brief looks familiar',text:'The next assessment asks for a structured explanation with evidence. The comments from the first piece would have been useful. You can still read them now, even though the deadline feels nearer.',options:[opt('Revisit the feedback and ask what you can improve','followAssessmentEnd',{flag:{assessPrepared:false}})]},
 followAssessmentEnd:{place:'library',speaker:'Aoife · lecturer',portrait:'lecturer',title:'And if the module is not passed?',text:s=>`${s.flags.assessPrepared?'You can identify a practical improvement to carry forward.':'You begin to see how feedback could help with the next task.'} Cian asks another question: “If I do badly on one assessment, is that the same as failing the whole module? And what happens then?”\n\nAoife explains that marks, component requirements, reassessment and progression depend on the approved module assessment strategy and current TU Dublin regulations. Neither a friend nor this game can guarantee a particular outcome.`,options:[opt('Check the module assessment details and official reassessment information; seek advice','hub',{flag:{assessmentFollowup:'checked'},note:'Follow-up case: a component result is not automatically a module result. Check official marking, reassessment and progression rules; use feedback for the next task.'}),opt('Assume one poor mark always means repeating the entire year','hub',{flag:{assessmentFollowup:'assumed'},note:'Follow-up case: do not infer a progression outcome from one mark; check the approved module requirements and current regulations.'})]},

 followTimetable1:{place:'east',speaker:'Cian · fellow student',portrait:'peer',title:'Week 4: the room has changed again',text:'It is ten minutes before a workshop. A new update names a different room for one activity. The curriculum profile still lists the module, but your saved image shows the original room. Cian worries that the module has been cancelled. The message is short and time matters.',options:[opt('Read the latest published change and locate the revised class activity','followTimetableRead',{flag:{timeTransfer:'verify'}}),opt('Go to the old room without checking because the screenshot looked official','followTimetableOld',{flag:{timeTransfer:'old'}})]},
 followTimetableRead:{place:'east',speaker:'Saoirse · classmate',portrait:'peer',title:'The latest version',text:'The timetable shows the same module and class time, but a different room. The published change identifies the moved activity. You have enough information to head to the right location. Saoirse asks what you would do if the room itself was impossible to access.',options:[opt('Keep the exact details and contact the responsible team','followTimetableEnd',{flag:{timeEvidence:true}})]},
 followTimetableOld:{place:'east',speaker:'Cian · fellow student',portrait:'peer',title:'An empty classroom',text:'You reach the old room. It is empty. A student outside shows you the newer published timetable. You now know the module has not vanished, but your saved screenshot was out of date.',options:[opt('Check the change notice and the correct room','followTimetableEnd',{flag:{timeEvidence:false}})]},
 followTimetableEnd:{place:'east',speaker:'Narrator',title:'One timetable, several kinds of information',text:s=>`${s.flags.timeEvidence?'You found the room change before travelling.':'You found the mismatch and corrected your route.'} A timetable shows activities and locations. A module profile shows the recorded academic build. If either appears inconsistent, the query should describe the module, day, time, room and version of the timetable.`,options:[opt('Save the details and raise a specific query only if the mismatch remains','hub',{flag:{timetableFollowup:'specific'},note:'Follow-up case: compare latest published timetable and module build; report exact activity details when a discrepancy persists.'}),opt('Treat a room change as proof that my module was removed','hub',{flag:{timetableFollowup:'confused'},note:'Follow-up case: a room or activity change does not automatically alter module registration.'})]},

 followExploration1:{place:'central',speaker:'Saoirse · classmate',portrait:'peer',title:'Week 6: a tempting new module',text:'Saoirse enjoyed a guest lecture and has found an introductory module that sounds perfect. It is not part of her current registered build. “I understand that I cannot just swap classes,” she says. “But surely it is too late to investigate it now?”\n\nYou have learned the difference between a new interest and a formal change. What is a useful next step?',options:[opt('Investigate possible future pathway use while keeping the current build clear','followExplorationExplore',{flag:{exploreTransfer:'future'}}),opt('Tell her she has lost every chance to study the subject','followExplorationShut',{flag:{exploreTransfer:'never'}})]},
 followExplorationExplore:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'The door is not necessarily closed',text:'“A new interest can sometimes be explored through later module choices, SARs, electives or a possible pathway,” Aoife says. “Whether this particular option is viable depends on the approved structure, sequencing, availability and timing. We should check rather than promise.”',options:[opt('Make a pathway enquiry without requesting an informal swap','followExplorationEnd',{flag:{exploreInvestigated:true}})]},
 followExplorationShut:{place:'central',speaker:'Saoirse · classmate',portrait:'peer',title:'An unnecessary full stop?',text:'Saoirse asks whether the module could be relevant next year or count as breadth later. You do not know. Saying “never” may shut down a reasonable academic curiosity. The better response is to distinguish what is possible to explore from what can be registered now.',options:[opt('Check the future possibilities and requirements','followExplorationEnd',{flag:{exploreInvestigated:false}})]},
 followExplorationEnd:{place:'central',speaker:'Narrator',title:'Exploring responsibly',text:'Saoirse has a new subject to investigate. Her current registration has not changed; neither has the university guaranteed a future place. You have helped preserve curiosity while making the official process visible.',options:[opt('Check the one-pager, sequencing and available advising route','hub',{flag:{explorationFollowup:'future'},note:'Follow-up case: explore a new area through future opportunities and approved pathways without implying free module swapping.'}),opt('Assume every desired subject can always be taken later','hub',{flag:{explorationFollowup:'unverified'},note:'Follow-up case: future possibilities still depend on prerequisites, availability, capacity and approved programme rules.'})]},

 followPreparation1:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'Week 10: what happened after the meeting?',text:'You open the notes from your advising meeting. You had several useful questions and agreed to check an introductory Major requirement. The module information has been published, but the question about capacity still needs an answer.\n\nJulie sends a message: “How did you get on with the actions we agreed?” An advising meeting is useful only if someone knows what happens next.',options:[opt('Review the written actions, what was answered and what is still outstanding','followPreparationReview',{flag:{prepTransfer:'review'}}),opt('Assume the adviser dealt with every action without checking','followPreparationWait',{flag:{prepTransfer:'assume'}})]},
 followPreparationReview:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'One answer, one outstanding item',text:'You can now distinguish what you learned in the meeting from what still requires confirmation. Julie can help with the academic implications; a capacity or registration decision requires the appropriate formal process. She asks whether you can describe the unresolved question precisely.',options:[opt('Write the outstanding question, responsible contact and proposed next step','followPreparationEnd',{flag:{prepFollowupReady:true}})]},
 followPreparationWait:{place:'central',speaker:'Julie · academic adviser',portrait:'adviser',title:'A conversation is not an automatic change',text:'“I made a note of what we discussed,” Julie explains, “but we agreed that we still needed to confirm an availability detail. Let us check the owner of that question.” You have not failed the meeting. You just need to make the follow-up explicit.',options:[opt('Clarify who will act and how I will know the outcome','followPreparationEnd',{flag:{prepFollowupReady:false}})]},
 followPreparationEnd:{place:'central',speaker:'Narrator',title:'Your advising record has a future',text:s=>`${s.flags.prepFollowupReady?'You leave with an organised note containing the open question and next action.':'You now understand why it helps to record outstanding questions after a useful conversation.'} Your Form A was a record of preferences and discussion. The practice timetable was a simulation; the real student profile and official process remain authoritative.`,options:[opt('Check status and record the outcome without treating it as confirmed registration','hub',{flag:{preparationFollowup:'tracked'},note:'Follow-up case: advising generates questions and actions; track unresolved items and verify decisions through official routes.'}),opt('Treat the discussion record as automatic module approval','hub',{flag:{preparationFollowup:'assumed'},note:'Follow-up case: Form A and advising discussion do not approve module registration or capacity exceptions.'})]},


 friendExplorationCentral:{place:'central',speaker:'Saoirse · classmate',portrait:'peer',title:'Another subject worth exploring',text:`Saoirse stops you at Central Quad. “I'm interested in studying something unexpected, but I can't tell whether that requires a module change now. Do you know who can help?”`,options:[opt('Discuss what exploration means for the current registration','explore1'),opt('Check the official guidance through the phone first','hub',{message:['Saoirse · a new academic interest','Do you want to check how exploration and module registration differ?']})]},
 friendWorkload:{place:'library',speaker:'Saoirse · classmate',portrait:'peer',title:'Is this really a day off?',text:`Saoirse is looking at the two empty days on her timetable. “I could take on extra shifts,” she says. “But I haven't worked out where my reading and assignments go. Do you know how the credits work?”\n\nYou can work through the question together rather than assuming a blank timetable means no learning.`,options:[opt('Explore workload and the 100-hour ECTS expectation together','work1'),opt('Check the example timetable first','practiceTimetable')]},
 friendSupport:{place:'rathdown',speaker:'Cian · fellow student',portrait:'peer',title:'Which desk should I ask?',text:`Cian has a question about a module and a separate personal concern. “I don't know who does what around here,” he says. “Can we figure out who actually helps?”`,options:[opt('Talk to the student-support colleague','support1'),opt('Check the phone contacts and supports first','hub',{message:['Cian · fellow student','Could we find out who to contact? The Student Hub and academic advising are not interchangeable.']})]},
 friendBelonging:{place:'lower',speaker:'Saoirse · classmate',portrait:'peer',title:'Will you come along?',text:`Saoirse points to a student event at Lower House. “I know it's awkward going on your own,” she says. “You don't have to join anything. But there's a project involving music, visual media and sustainability that sounds interesting.”`,options:[opt('Talk about the invitation and what it might lead to','belong1'),opt('Keep the invitation in my phone for later','hub',{message:['Saoirse · Lower House','There is an open student event. Come over if you feel like it; no pressure.']})]},
 friendPreparation:{place:'library',speaker:'Cian · fellow student',portrait:'peer',title:'Meeting your adviser tomorrow?',text:`Cian asks if you have prepared for your advising meeting. “I'm not sure whether to bring my timetable, my interests, or just questions,” he says. “What did you do last time?”`,options:[opt('Work through the preparation scenario with Cian','prep1'),opt('Check Form A and the timetable in my phone first','practiceForm')]},

 /* v1.3: Real-world-style referrals: an introduction by a friend or a phone alert, then a physical campus journey. */
 routeMissingStart:{place:'central',speaker:'Cian · fellow student',portrait:'peer',title:'The module that never appeared',text:`Cian catches you outside Central Quad. “I was told first year is about trying different subjects. I went to an introductory talk on Tuesday, but the class still isn’t on my timetable. A lecturer said I could come along. I don’t know whether that counts.”

They show you an invitation to a taster session, not a registration confirmation. “I could email everyone,” Cian says, “or maybe there’s somebody who could tell me what this means for my degree.”`,options:[opt('Ask Cian which subject and future pathway they hope to keep open','routeMissingRefer',{flag:{routeMissingChoice:'pathway'}}),opt('Suggest that Cian attends and assumes the credits will appear','routeMissingRefer',{flag:{routeMissingChoice:'assume'}}),opt('Check the practice Curriculum Planner before advising','practiceTimetable',{flag:{routeMissingChoice:'profile'}})]},
 routeMissingRefer:{place:'lower',speaker:'Cian · fellow student',portrait:'peer',title:'A reason to speak to the adviser',text:s=>`${s.flags.routeMissingChoice==='assume'?'Cian points out that they could attend for weeks without appearing on the module list. “That would be awful at assessment time.”':'Together you work out that the question is about both a possible academic pathway and a missing formal allocation.'}\n\nCian has a copy of their timetable but is unsure what their preferred Major might require. You agree to speak to Julie at Central Quad before assuming anything about changing modules.`,options:[opt('Add Julie to the phone, then travel to Central Quad','hub',{referral:{id:'missing-adviser',place:'central',placeName:'Central Quad',scene:'routeMissingAdviser',contact:'Julie · Academic Adviser',why:'Discuss the pathway interest and identify which registration question needs formal checking.'}})]},
 routeMissingAdviser:{place:'central',speaker:'Julie · Academic Adviser',portrait:'adviser',title:'An academic question and a registration question',text:`You find Julie at Central Quad and show her the introductory invitation and the fictional student profile.

“It’s good that you’re exploring,” she says. “But being invited into a room doesn’t mean someone has registered you for a module. I can help work out whether it matters for a future Major. I can’t promise a place or alter the official build through this conversation.”

She asks you to decide what information the programme team needs.`,options:[opt('Record the module code, the published build and why it matters','routeMissingToSupport',{flag:{routeMissingEvidence:'complete'}}),opt('Ask the programme team simply to add every preferred module','routeMissingToSupport',{flag:{routeMissingEvidence:'vague'}})]},
 routeMissingToSupport:{place:'central',speaker:'Julie · Academic Adviser',portrait:'adviser',title:'One more person to see',text:s=>`${s.flags.routeMissingEvidence==='vague'?'Julie asks for the actual module and timetable details first; otherwise the programme team would have to guess which record to investigate.':'Aoife helps you set out the actual question rather than sending an open-ended complaint.'}\n\n“Take this to the programme support contact at Rathdown House. They can check the administrative status and explain where a registration query goes. Afterwards, come back to me if there are pathway implications.”`,options:[opt('Put the referral in my phone and go to Rathdown House','hub',{referral:{id:'missing-support',place:'rathdown',placeName:'Rathdown House',scene:'routeMissingSupport',contact:'Programme support',why:'Check the difference between the published build, an invitation and confirmed registration.'}})]},
 routeMissingSupport:{place:'rathdown',speaker:'Máire · programme support',portrait:'support',title:'What the system can actually confirm',text:`At Rathdown House, Máire listens and compares the information you’ve brought. “The example invitation is for an introductory talk,” she says. “The practice profile still shows the original build. We can’t treat the talk as a module registration.”

Máire explains that actual availability, allocation and registration require the university’s authorised procedures. She cannot offer an instant place. She can identify what has to be checked and who will communicate the decision.`,options:[opt('Record the status and return to the adviser to discuss options','hub',{flag:{routeMissingResolved:'checked'},referral:{id:'missing-return',place:'central',placeName:'Central Quad',scene:'routeMissingFinal',contact:'Julie · Academic Adviser',why:'Discuss what the administrative answer means for future pathways.'}}),opt('Assume the discussion itself added the module','hub',{flag:{routeMissingResolved:'assumed'},referral:{id:'missing-return',place:'central',placeName:'Central Quad',scene:'routeMissingFinal',contact:'Julie · Academic Adviser',why:'Clarify why a support conversation does not itself update the registered build.'}})]},
 routeMissingFinal:{place:'central',speaker:'Julie · Academic Adviser',portrait:'adviser',title:'The question has moved forward',text:s=>`${s.flags.routeMissingResolved==='assumed'?'Julie checks the latest build with you. It has not changed. The visit was an enquiry, not confirmation.':'Julie reviews the information that the programme support team explained.'}\n\n“You now have two useful things,” she says. “An honest answer about the current record and a question we can investigate about future study. Sometimes university problems need more than one person. The useful outcome is knowing what is confirmed, what is being checked and who will come back to you.”`,options:[opt('Save the outcome and return to campus','hub',{clearReferral:true,flag:{missingRouteComplete:true},note:'Completed multi-person case: Cian → Academic Adviser → Programme support → Academic Adviser. No registration was changed.'})]},

 routeAssessmentStart:{place:'library',speaker:'Saoirse · classmate',portrait:'peer',title:'The mark on the assignment',text:`Saoirse is sitting at a table in the Academic Hub, staring at a returned assignment. “I got 38. Does that mean I’ve failed the whole module, or even my year? I don’t want to ask a stupid question.”

You remember that the answer depends on the assessment scheme and any specific pass requirements. A classmate can’t infer the final result from one component mark. But Saoirse needs help with the feedback today.`,options:[opt('Suggest asking the module lecturer about the rubric and feedback','hub',{flag:{routeAssessApproach:'lecturer'},referral:{id:'assess-lecturer',place:'east',placeName:'East Quad',scene:'routeAssessmentLecturer',contact:'Ms Ní Chonaill · Module Lecturer',why:'Clarify feedback, assessment weights and any component-specific requirements.'}}),opt('Tell Saoirse everyone gets an automatic resit','hub',{flag:{routeAssessApproach:'assume'},referral:{id:'assess-lecturer',place:'east',placeName:'East Quad',scene:'routeAssessmentLecturer',contact:'Ms Ní Chonaill · Module Lecturer',why:'Check the module assessment scheme rather than assuming an entitlement.'}})]},
 routeAssessmentLecturer:{place:'east',speaker:'Ms Ní Chonaill · lecturer',portrait:'lecturer',title:'A mark needs its context',text:s=>`${s.flags.routeAssessApproach==='assume'?'“An automatic resit isn’t something I can promise from a single mark,” the lecturer explains.':'The lecturer is pleased Saoirse brought the actual brief and feedback.'}\n\nShe shows you how the assessment components and their weights are described in the module information. “This isn’t the same as a final module result. We can talk about improving the next piece, but official decisions about reassessment and progression follow the current university rules.”\n\nShe suggests visiting the library’s learning support resources to develop a concrete plan.`,options:[opt('Go to the Academic Hub to work through the feedback','hub',{referral:{id:'assess-library',place:'library',placeName:'Academic Hub & Library',scene:'routeAssessmentLibrary',contact:'Library learning support',why:'Turn the feedback into a plan for the next assessment.'}})]},
 routeAssessmentLibrary:{place:'library',speaker:'Niamh · learning support',portrait:'support',title:'What can change next time?',text:`Niamh helps you and Saoirse compare the assignment feedback with the original marking criteria. There are two specific problems: evidence was not well supported, and the conclusion didn’t answer the question.

“What do you want to do with that information?” she asks. You can read about referencing and arrange a study-skills conversation. Neither changes the mark already awarded.`,options:[opt('Make a realistic revision plan and revisit the lecturer with one question','hub',{flag:{routeAssessPrepared:true},referral:{id:'assess-return',place:'east',placeName:'East Quad',scene:'routeAssessmentFinal',contact:'Ms Ní Chonaill · Module Lecturer',why:'Clarify the next assessment and check where formal results or progression advice comes from.'}}),opt('Ask the support tutor to change the mark','hub',{flag:{routeAssessPrepared:false},referral:{id:'assess-return',place:'east',placeName:'East Quad',scene:'routeAssessmentFinal',contact:'Ms Ní Chonaill · Module Lecturer',why:'Clarify the difference between learning support and formal academic decisions.'}})]},
 routeAssessmentFinal:{place:'east',speaker:'Ms Ní Chonaill · lecturer',portrait:'lecturer',title:'A plan, not a promise',text:s=>`${s.flags.routeAssessPrepared?'Saoirse returns with a plan for using stronger evidence and checking the rubric before submitting.':'You return with an important distinction clarified: learning support can help with the next task but cannot change official marks.'}\n\nThe lecturer answers the remaining question about the next task and points to the official module assessment and university regulations for any eventual reassessment or progression question. Saoirse still feels disappointed, but now has useful next steps.`,options:[opt('Record the follow-up and return to campus','hub',{clearReferral:true,flag:{assessmentRouteComplete:true},note:'Completed multi-person case: Saoirse → Lecturer → Learning support → Lecturer. No result or reassessment was guaranteed.'})]},

 routeTimetableStart:{place:'central',speaker:'Cian · fellow student',portrait:'peer',title:'Two versions of Friday',text:`Cian holds up a screenshot of last week’s timetable. His phone is showing something different. “I’ve got a workshop in East Quad on one version, and a different time on the other. Which do I follow?”

You know the latest published timetable is the starting point, but the class location may still need checking.`,options:[opt('Check the current timetable and compare the change notice','hub',{flag:{routeTimetableChecked:true},referral:{id:'time-support',place:'rathdown',placeName:'Rathdown House',scene:'routeTimetableSupport',contact:'Programme support',why:'Find out whether this is a published activity change or an unresolved timetable query.'}}),opt('Trust the older screenshot because it has a date','hub',{flag:{routeTimetableChecked:false},referral:{id:'time-support',place:'rathdown',placeName:'Rathdown House',scene:'routeTimetableSupport',contact:'Programme support',why:'Check which timetable publication is authoritative.'}})]},
 routeTimetableSupport:{place:'rathdown',speaker:'Máire · programme support',portrait:'support',title:'A timetable update is not a module change',text:s=>`${s.flags.routeTimetableChecked?'You can describe both versions and the changed activity.':'Máire asks you to open the latest published version before trying to interpret the old screenshot.'}\n\n“The module is still on the fictional build,” she explains. “This looks like a change in the scheduled activity. If the room or time is unclear, the teaching team can confirm the class details. Let’s check the exact workshop.”`,options:[opt('Travel to East Quad and check the workshop with the lecturer','hub',{referral:{id:'time-lecturer',place:'east',placeName:'East Quad',scene:'routeTimetableLecturer',contact:'Workshop lecturer',why:'Confirm the class activity location without assuming registration has changed.'}})]},
 routeTimetableLecturer:{place:'east',speaker:'Ms Ní Chonaill · lecturer',portrait:'lecturer',title:'Finding the right workshop',text:`You reach East Quad and check the teaching notice. The workshop is running at the revised time in the updated room. “Changes happen,” the lecturer says. “The important thing is to check the published source and tell us if there is a genuine conflict.”

A revised class activity doesn’t remove a module from the academic record.`,options:[opt('Save the confirmed practical details and finish the enquiry','hub',{clearReferral:true,flag:{timetableRouteComplete:true},note:'Completed multi-person case: Cian → programme support → lecturer at East Quad. Class changes and module registration are different.'})]},

 routeExplorationStart:{place:'east',speaker:'Saoirse · classmate',portrait:'peer',title:'The subject you did not expect to love',text:`At East Quad, Saoirse tells you about an Irish-language and media project she visited. “I thought I wanted one Major, but now I’m curious about something completely different. Does that mean I need to change this semester’s modules?”

It’s a genuinely positive discovery. You want to encourage it without promising she can swap a registered module.`,options:[opt('Suggest discussing future pathways with an academic adviser','hub',{referral:{id:'explore-adviser',place:'central',placeName:'Central Quad',scene:'routeExplorationAdviser',contact:'Julie · Academic Adviser',why:'Explore the new interest and check what needs planning now.'}}),opt('Tell her interests are fixed after induction','hub',{flag:{exploreClosed:true},referral:{id:'explore-adviser',place:'central',placeName:'Central Quad',scene:'routeExplorationAdviser',contact:'Julie · Academic Adviser',why:'Check whether a new interest can inform later choices.'}})]},
 routeExplorationAdviser:{place:'central',speaker:'Julie · Academic Adviser',portrait:'adviser',title:'Exploration does not stop at the timetable',text:s=>`${s.flags.exploreClosed?'“We shouldn’t close down a possible interest without checking,” Julie says.':'Julie encourages Saoirse to keep investigating the interest.'}\n\nThe adviser helps identify possible Major, Minor or breadth routes, but says the subject-owning team is better placed to explain its module sequence and any prerequisites. “You don’t need to commit today. You do need reliable information about the possibilities.”`,options:[opt('Meet the subject lecturer at East Quad','hub',{referral:{id:'explore-school',place:'east',placeName:'East Quad',scene:'routeExplorationSchool',contact:'Subject lecturer',why:'Ask about introductory modules, prerequisites and sequencing before making promises.'}})]},
 routeExplorationSchool:{place:'east',speaker:'Ms Ní Chonaill · subject lecturer',portrait:'lecturer',title:'A possible direction',text:`The subject lecturer describes an example sequence: one introductory learning experience leads into more advanced work. The actual sequence depends on the approved Major or Minor documentation.

Saoirse is pleased to discover there are ways to investigate a subject without automatically changing the current timetable. But she wants to know how this might fit her whole Arts degree.`,options:[opt('Return to Julie to compare it with the broader degree structure','hub',{referral:{id:'explore-return',place:'central',placeName:'Central Quad',scene:'routeExplorationFinal',contact:'Julie · Academic Adviser',why:'Compare the subject information with the overall BA Arts pathway.'}})]},
 routeExplorationFinal:{place:'central',speaker:'Julie · Academic Adviser',portrait:'adviser',title:'Keep the curiosity, check the route',text:`At Central Quad, you compare the subject information with the practice pathway profile. Julie explains why overall degree requirements and the subject-specific sequence both matter.

Saoirse has discovered something worth following up. Her registered modules have not changed. She knows which people and resources can help her make a future decision.`,options:[opt('Record the possible pathway and complete the case','hub',{clearReferral:true,flag:{explorationRouteComplete:true},note:'Completed multi-person case: Saoirse → adviser → subject lecturer → adviser. Exploration is encouraged; registration remains separate.'})]},
 /* Week 3 checkpoint */
 week3:{place:'lower',speaker:'Cian · fellow student',portrait:'peer',title:'Optional reflection: Earlier choices return',text:s=>{
 const w=s.flags.workStyle==='unplanned'?'Cian mentions an upcoming submission. You realise the blank days you treated as completely free are also useful study time.':s.flags.workStyle==='plan'?'Your early decision to look at module workload helps as submissions approach. There are still things to juggle, but your plan is a starting point.':'You remember checking whether your timetable was correct. Now you need to decide how to use the remaining free time.';
 const t=s.flags.changeRead?'You also checked a published timetable change instead of relying on an old screenshot.':'A new timetable notification reminds you to check the latest published version.';
 const p=s.flags.pathway==='checked'?'You have already flagged the early gateway question for possible future Majors.':'A possible Major comes up again. You have not yet checked whether an early sequence matters.';
 return `<p>${w}</p><div class="scene-note">${p}</div><p>${t}</p><p>Cian asks, “What’s one thing you wish somebody had told us on the first day?”`},options:[opt('“That asking the right person makes everything less confusing.”','week3End',{flag:{reflection:'contacts'}}),opt('“That free timetable space is not empty workload.”','week3End',{flag:{reflection:'workload'}}),opt('“That I can explore, but some options need early planning.”','week3End',{flag:{reflection:'pathways'}})]},
 week3End:{place:'lower',speaker:'Narrator',title:'Your story continues',text:'You have not solved every challenge university will bring. You have learned a few ways of navigating it — who to ask, what to check, when to act, and how to keep exploring.',options:[opt('See your first-weeks story','ending',{flag:{finished:true}})]},
 revisit:{place:s=>places.find(p=>p.id===s.flags.revisitPlace)?.id||'central',speaker:'Narrator',title:'A familiar place',text:s=>`You return to ${places.find(p=>p.id===s.flags.revisitPlace)?.name||'campus'}. You already completed the main encounter here. The contact and note remain in your phone.`,options:[opt('Return to campus','hub')]}
};

function guideMarkup(){return `<section class="panel guide"><div class="dialogue"><div class="chapter">Optional reading alternative · v1.1</div><h1 id="scene-title" tabindex="-1">How your Arts degree works</h1><p>The BA Arts (TU980) is a four-year honours degree. You normally complete 60 ECTS each year, 30 ECTS per semester and 240 ECTS overall. TU Dublin estimates 100 hours of total learning effort for each 5 ECTS module, including scheduled classes, independent study and assessment. A module has learning outcomes, scheduled learning activities and assessment requirements.</p><p>Everyone must complete an approved Major (80, 100 or 120 ECTS), the 30 ECTS shared Spine and 50 ECTS of Subject Area Requirements (SARs). A 40 ECTS Minor is optional. Free Electives depend on available space and programme rules. Reaching 240 ECTS by itself is not enough: you must satisfy the approved award requirements.</p><p>Stage 1 is an opportunity to explore interests and possible future pathways. It does <strong>not</strong> mean you can freely exchange registered modules. A preference is not a confirmed allocation or registration. Some choices have prerequisites, capacity limits, timetable restrictions or earlier planning needs. Stage 1 pathway preferences are indicative; formal Major confirmation comes later in Stage 2.</p><p>For assessment, check each module descriptor and brief. A disappointing mark on one assessment does not automatically mean failing the module; reassessment and progression depend on the specific module and current official regulations. Ask your lecturer or relevant university staff for clarification.</p><p>Before advising: check your current Curriculum Planner and timetable, write down interests and questions, and identify any constraints. Afterwards, record next steps. Advising conversations do not themselves change registration.</p><p>This short guide is a learning summary, not definitive programme or assessment advice. Check the <a href="https://tudublin.sharepoint.com/sites/ARTS-Hub/SitePages/FAQ%20landing%20page.aspx" target="_blank" rel="noopener noreferrer">real Arts Hub</a> and <a href="https://examreports-tudublin.msappproxy.net/examportal/curriculum-planner/" target="_blank" rel="noopener noreferrer">real Curriculum Planner</a> for current information.</p><div class="footer-actions"><button class="choice primary" data-next="hub">Return to campus</button></div></div></section>`}
function exitSurveyMarkup(state){const answers=state.exitAnswers||{};const r=(key,value)=>answers[key]===value?'checked':'';return `<section class="panel survey"><div class="dialogue"><div class="chapter">Optional, private reflection · takes about 1 minute</div><h1 id="scene-title" tabindex="-1">How was your experience?</h1><p>This is a <strong>development survey</strong>, not a university assessment. There are no right answers. Your responses stay on this device unless you choose to copy them and share them separately. You may skip everything.</p><form id="exit-survey"><fieldset><legend>1. I understand better how BA Arts is structured.</legend><label><input type="radio" name="structure" value="yes" ${r('structure','yes')}> Yes</label><label><input type="radio" name="structure" value="somewhat" ${r('structure','somewhat')}> Somewhat</label><label><input type="radio" name="structure" value="no" ${r('structure','no')}> Not yet</label></fieldset><fieldset><legend>2. I feel more confident knowing where to check a module or pathway question.</legend><label><input type="radio" name="navigation" value="yes" ${r('navigation','yes')}> Yes</label><label><input type="radio" name="navigation" value="somewhat" ${r('navigation','somewhat')}> Somewhat</label><label><input type="radio" name="navigation" value="no" ${r('navigation','no')}> Not yet</label></fieldset><fieldset><legend>3. What should we improve first? (optional)</legend><label><input type="radio" name="improve" value="clarity" ${r('improve','clarity')}> Clearer explanations</label><label><input type="radio" name="improve" value="story" ${r('improve','story')}> More interesting decisions and story</label><label><input type="radio" name="improve" value="length" ${r('improve','length')}> Shorter or easier to navigate</label><label><input type="radio" name="improve" value="accessibility" ${r('improve','accessibility')}> Better readability or accessibility</label><label><input type="radio" name="improve" value="other" ${r('improve','other')}> Something else</label></fieldset><label for="exit-comment"><strong>One thing you would change (optional)</strong></label><textarea id="exit-comment" name="comment" maxlength="300" rows="3" placeholder="Please do not include names or personal information.">${html(answers.comment||'')}</textarea><p id="survey-message" class="help" aria-live="polite">Answers are not transmitted. Do not include identifying or sensitive information.</p><div class="footer-actions"><button type="submit" class="choice primary">Save my reflection on this device</button><button type="button" class="choice" data-survey-copy="1">Copy feedback</button><button type="button" class="choice" data-next="ending">Skip / back to my story</button></div></form></div></section>`}

function renderEnding(state){const lines=[state.flags.explorationCompleted?(state.flags.transferAnswer==='check'?'You correctly applied the exploration/registration distinction in a new case.':'You tested how exploration differs from changing registered modules.'):'You can still investigate what Stage 1 exploration actually allows.',state.flags.moduleAssumption==='turnup'?'You learned that simply turning up is not the same as registration.':'You investigated the difference between preference and registration.',state.flags.pathway==='checked'?'You checked a possible Major sequence early.':'You still have a possible Major requirement to check.',state.flags.workStyle==='unplanned'?'Your unplanned timetable gaps created a question for Week 3.':'You began thinking about independent workload.',state.flags.social==='connected'?'You considered making a social connection through a society.':'You found out about the Students’ Union and student life.'];return `<div class="panel ending"><div class="chapter">First Semester · Your story so far</div><h1>Well played, ${html(state.name)}.</h1><p>${state.flags.guidedFinished?'You have completed the seven-chapter simulated semester.':'You can continue the guided semester chapters at any time.'} The goal was not to make every perfect choice. It was to begin seeing how academic decisions, institutional services and student life connect.</p><div class="ending-grid"><div class="item"><strong>Guided learning journey</strong>${state.chapterDone.length} of 7 chapters completed. ${state.flags.guidedFinished?'A possible graduation reflection is part of your story.':'Return to the campus to complete the semester story.'}</div>${lines.map((x,i)=>`<div class="item"><strong>${['Exploration and change','Registration','Future pathways','Time and workload','Belonging'][i]}</strong>${html(x)}</div>`).join('')}</div><p><strong>Further situations you practised:</strong> ${Object.keys(state.flags).filter(k=>k.endsWith('Followup')).length} follow-up cases revisited after an initial issue. An answer is a starting point; check official guidance before applying it in real life.</p><p><strong>One-minute optional exit reflection:</strong> Tell us what helped or remained unclear. Feedback remains on this device until you choose to copy it.</p><p><strong>Your next move:</strong> if something is unclear in real life, check official programme information and speak to the appropriate person. This fictional game cannot confirm a registration or approve an academic pathway.</p><div class="footer-actions"><button class="choice primary" data-next="hub">Keep exploring campus</button><button class="choice" onclick="reset()">Start a new story</button><button class="choice" onclick="window.print()">Print reflection</button><button class="choice primary" data-next="survey">Optional one-minute feedback</button></div><p class="help">Game design prototype — not university advice or an official TU Dublin product.</p></div>`}

export {N as nodes, CHAPTERS as chapters, places, FRIEND_LEADS as leads, missionInfo, base, MODULES as modules, makeModules, storyMarkup, degreeMarkup, guideMarkup, exitSurveyMarkup, renderEnding};
